const IDIOM_DATA = [
  // ========== 第 1—10 页 ==========
  { idiom: "防微杜渐", meaning: "指在错误或坏事刚露出苗头时就加以制止，不让它发展。强调及早防范、把问题消灭在萌芽状态，多用于形容预防不良事态扩大的意识与行动。褒义。", context: "党风廉政建设要防微杜渐，对苗头性问题早发现、早提醒、早纠正。" },
  { idiom: "积微成著", meaning: "指微小的事物积累多了，就会变得显著。强调积少成多、由量变到质变的过程，多用于形容长期积累带来的显著变化。中性或褒义。", context: "他坚持每日读书写作，积微成著，十年间竟积累了数百万字的手稿。" },
  { idiom: "慎小谨微", meaning: "指对细小的事情也小心谨慎，不敢疏忽。强调在小事上保持高度警惕和审慎态度，不因细微而大意，多用于形容做事细致周到的作风。褒义。", context: "安全工作必须慎小谨微，任何一个不起眼的隐患都可能酿成大祸。" },
  { idiom: "曲突徙薪", meaning: "指把烟囱改弯、把柴草搬走，比喻事先采取措施，防止灾祸。强调事前预防远胜于事后补救，多用于形容有远见的防范意识。褒义。", context: "与其等事故发生后再追责，不如曲突徙薪，提前排查并消除安全隐患。" },
  { idiom: "未卜先知", meaning: "指没有占卜就能事先知道，形容有预见性。强调事前就能预知未来的结果或趋势，多用于形容人的预见能力或神奇的先见之明。中性或褒义。", context: "气象卫星的应用让人类拥有了未卜先知的能力，可以提前预测台风路径并做好防范。" },
  { idiom: "明察秋毫", meaning: "形容目光敏锐，能看清极细小的东西。强调观察细致入微、洞察力极强，多用于形容能看清别人看不清的细节，多指对真相的洞察能力。褒义。", context: "监察机关要明察秋毫，不放过任何违纪违法的蛛丝马迹。" },
  { idiom: "洞若观火", meaning: "形容观察事物非常清楚，像看火一样清晰。强调对事物的本质和来龙去脉了解得极其透彻，多用于形容对局势、问题的深刻把握。褒义。", context: "他对行业的运行规律洞若观火，总能做出精准的判断和预测。" },
  { idiom: "随机应变", meaning: "指随着时机或情况的变化而灵活应付。强调灵活变通、不僵化，能够根据实际情况迅速调整策略，多用于形容处事灵活、反应敏捷。褒义。", context: "主持人随机应变，巧妙化解了直播中出现的突发状况。" },
  { idiom: "瞬息万变", meaning: "形容在极短的时间内发生了千变万化。强调变化的速度极快、频率极高，多用于形容局势、市场、天气等的急剧变化。中性。", context: "互联网时代，信息瞬息万变，我们需要不断提升自身的判断力和适应力。" },
  { idiom: "一触即发", meaning: "指形势紧张到了极点，稍一触动就会立刻爆发。强调极度紧张、随时可能发生冲突或巨变的状态，多用于形容战争、危机、矛盾等一触即发的紧迫局面。中性或略带贬义。", context: "边境线上气氛紧张，冲突一触即发，国际社会纷纷呼吁双方保持克制。" },
  { idiom: "变幻莫测", meaning: "指事物变化多端，难以预料。强调变化复杂且无法捉摸，难以预测其走向，多用于形容天气、命运、局势等。中性。", context: "高原天气变幻莫测，刚才还是晴空万里，转眼间狂风大作。" },
  { idiom: "波谲云诡", meaning: "指像云彩和水波那样形态万千、难以捉摸。形容事物变幻莫测、奇异多姿，多用于形容局势、事态发展变化快且复杂难料，也用于形容文章、想象等奇幻多姿。中性（贬义或褒义视语境而定）。谲：狡诈、怪异。此处指事物变化奇特、诡秘，非常理可测。强调计谋上的诡诈，如“权谋谲诈”。诡：奇异、狡诈。此处指变幻莫测、难以捉摸。强调表象上的离奇，如“诡异”。", context: "国际局势波谲云诡，我们必须在复杂形势中保持战略定力。" },
  { idiom: "按部就班", meaning: "指按照一定的步骤、顺序进行。强调做事遵循规范、有条不紊，多用于形容工作或学习按既定程序推进。中性（略带保守意味）。", context: "项目建设要按部就班，严格遵循施工流程，确保工程质量。" },
  { idiom: "从长计议", meaning: "指花费较长的时间慎重地考虑、商议。强调不急于做决定，从长远角度审慎谋划，多用于需要慎重决策的重大事项。中性或褒义。", context: "这项改革涉及面广、影响深远，需要从长计议，充分听取各方意见后再稳步推进。" },
  { idiom: "稳扎稳打", meaning: "指步步为营、稳妥地进行，比喻做事稳妥踏实。强调不冒进、不急于求成，一步一个脚印地推进，多用于形容工作方法或战略。褒义。", context: "企业发展要稳扎稳打，不能盲目扩张，否则容易陷入困境。" },
  { idiom: "以守为攻", meaning: "指以防御作为进攻的手段，通过稳固防守来消耗对方、寻找战机。强调在防守中积蓄力量、伺机反攻，多用于形容战术、策略上的智慧。褒义。", context: "在市场竞争中，这家企业采取了以守为攻的策略，先稳固核心业务，再逐步拓展新领域。" },
  { idiom: "持重待机", meaning: "指行事稳重谨慎，不轻举妄动，耐心等待合适的时机。强调以沉稳的态度应对局势，在时机成熟之前不贸然行动，多用于形容军事、政治、商业等领域的策略性等待。褒义。", context: "面对复杂的市场环境，企业应当持重待机，在保持核心竞争力的同时耐心等待最佳的发展契机。" },
  { idiom: "抽丝剥茧", meaning: "指抽出丝、剥去茧，比喻层层深入地剖析问题、分析事物。强调逐步深入、由外及内、细致入微地探究事物的本质，多用于形容分析问题、推理过程等。褒义。", context: "记者通过抽丝剥茧式的调查，终于揭开了这起事件背后的真相。" },
  { idiom: "循序渐进", meaning: "指按照一定的步骤或顺序逐渐深入或提高。强调遵循规律、由浅入深、逐步推进，多用于形容学习、工作、改革等的推进方式。褒义。", context: "学习语言是一个循序渐进的过程，不能急于求成，需要日积月累。" },
  { idiom: "由表及里", meaning: "指从表面现象深入到内在本质。强调认识或分析问题时不局限于表面，而是层层深入、由外向内，多用于形容观察、分析、认识事物的方法。中性或褒义。", context: "调查研究要由表及里，透过现象看本质，才能真正发现问题所在。" },
  { idiom: "自上向下", meaning: "指从上到下、由高到低，也指从整体到局部、从宏观到微观。强调顺序上的层级递减，多用于描述管理路径、信息传递、空间顺序等。中性。", context: "政策的传达通常是自上向下层层推进的，确保各级都能准确理解执行。" },
  { idiom: "捉襟见肘", meaning: "指拉一下衣襟胳膊肘就露出来，形容衣服破烂，也比喻生活困难或处境窘迫、顾此失彼。强调资源不足、难以周全，多用于形容经济拮据、管理困难或工作应接不暇的状态。贬义或中性。", context: "由于资金短缺，这项工程的进展捉襟见肘，许多环节不得不被迫放缓。" },
  { idiom: "进退维谷", meaning: "指无论是前进还是后退，都处于困境之中。强调处境艰难、左右为难，无论怎么做都难以摆脱困境，多用于形容面临两难选择时的无奈状态。贬义。", context: "公司面临资金链断裂的危机，他进退维谷，既无法继续支撑，也难以全身而退。" },
  { idiom: "得不偿失", meaning: "指得到的利益抵偿不了所受的损失。强调付出与回报不成正比、亏本或得不值当，多用于评价行为、投资、决策等的效果。贬义。", context: "为了短期利益而破坏环境，最终只会得不偿失，给后代留下沉重的生态负债。" },
  { idiom: "左支右出", meaning: "指力量不足，应付了这一方面，那一方面又有了问题。强调顾此失彼、疲于应对，多用于形容因资源、能力有限而难以兼顾的窘迫局面。贬义。", context: "基层工作千头万绪，人手严重不足，常常左支右出，难免出现疏漏。" },
  { idiom: "不求甚解", meaning: "指只求懂个大概，不求深刻理解。强调学习或读书时不深入钻研、只停留在表面，多用于批评马虎的学习态度。贬义（今多用于否定语境）。", context: "对待专业知识，我们应采取严谨态度，切莫不求甚解，否则难以胜任实际工作。" },
  { idiom: "不知所措", meaning: "指不知道怎么办才好，形容受窘或发急的状态。强调面对突发情况时因缺乏准备而陷入慌乱、不知如何应对的状态。贬义或中性。", context: "面对突如其来的故障，年轻的技术员一时间不知所措，幸好老前辈及时到场指挥。" },
  { idiom: "望洋兴叹", meaning: "原指在伟大的事物面前感叹自己的渺小，现多比喻因力量不足或条件不具备而感到无可奈何。强调面对宏大目标或困难时自感无能为力、徒叹奈何。中性或略带贬义。", context: "面对高昂的房价，许多年轻人只能望洋兴叹，暂时放弃购房计划。" },
  { idiom: "望而却步", meaning: "指看到了危险或阻力，就畏缩后退。强调因看到困难、危险或障碍而不敢前进，多用于形容在困难面前的退缩心理。贬义或中性。", context: "这项技术门槛极高，许多中小企业因此望而却步，不敢轻易涉足。" },
  { idiom: "大浪淘沙", meaning: "指在大浪中冲洗沙石，比喻在激烈的斗争中经受考验、筛选，留下精华、淘汰糟粕。强调经过时间或环境的检验，最终留下真正有价值的事物。中性或褒义。", context: "在历史的大浪淘沙中，只有那些真正为人民谋福祉的政策才能长久留存。" },
  { idiom: "精挑细选", meaning: "指非常仔细地挑选。强调在众多选择中反复比较、谨慎筛选，过程严谨细致，不轻易定夺。褒义。", context: "这家茶庄对每一批茶叶都精挑细选，确保送到顾客手中的都是上等佳品。" },
  { idiom: "优胜劣汰", meaning: "指优秀的得以胜出、劣质的被淘汰，是自然界和社会竞争中普遍存在的法则。强调在竞争中凭实力和适应性决定存留，多用于形容市场竞争、人才选拔、自然进化等领域。中性或褒义（视语境而定）。", context: "市场竞争遵循优胜劣汰的规律，企业只有不断创新，才能在激烈的竞争中立足。" },
  { idiom: "千锤百炼", meaning: "指经过千万次捶打和冶炼，比喻经历多次艰苦的锻炼和考验。强调经过长期反复的磨炼、实践而变得精纯或坚强，多用于形容人才、作品、技艺等的锻造过程。褒义。", context: "这支队伍经过多次实战演练的千锤百炼，已经具备了极强的应急处置能力。" },
  { idiom: "防不胜防", meaning: "指想要防备却来不及防备，形容防备不过来。强调危险或问题太多太突然，难以全面防范，多用于形容安全漏洞频出、坏现象层出不穷的状态。贬义或中性。", context: "网络诈骗手段花样翻新，令人防不胜防，公众需提高警惕。" },
  { idiom: "形同虚设", meaning: "指形式上虽有，却不起作用，如同虚设一样。强调外表存在但实际上毫无功能或效力，多用于形容制度、机构、措施等名不副实。贬义。", context: "如果监管不到位，再严格的法律也形同虚设，无法真正约束违法行为。" },
  { idiom: "名存实亡", meaning: "指名义上还有，实际上已经不存在了。强调徒有虚名、实质已空，多用于形容组织、制度、传统等在形式上保留但实质上已经消失或失效。贬义。", context: "由于长期缺乏维护，这项古老的民间技艺已经名存实亡，亟待抢救性保护。" },
  { idiom: "鞭长莫及", meaning: "比喻力量达不到，无法顾及或控制。强调受距离、能力等条件限制而难以发挥作用，多用于形容管理、救助、控制等力不从心。中性或略带贬义。", context: "偏远山区的基础设施薄弱，一些政策在落实时往往鞭长莫及，难以覆盖到位。" },
  { idiom: "按图索骥", meaning: "指按照图像去寻找好马，比喻按照线索去寻找事物，也比喻办事机械、死板。强调遵循线索或标准去寻找、办事，可褒（按线索办事）可贬（死板不知变通）。中性（视语境而定）。", context: "警方按图索骥，根据监控视频中的线索成功抓获了犯罪嫌疑人。" },
  { idiom: "守株待兔", meaning: "指守在树桩旁等待撞上来的兔子，比喻不主动努力而存有侥幸心理，希望得到意外的收获。强调死守狭隘经验、妄想不劳而获，多用于批评被动等待、不思进取的态度。贬义。", context: "学习没有捷径可走，不能有守株待兔的侥幸心理，必须脚踏实地。" },
  { idiom: "偷天换日", meaning: "比喻暗中改变事物的真相，以达到欺骗的目的。强调以隐蔽手段偷换关键内容、混淆视听，多用于形容欺诈、作弊、篡改等恶劣行为。贬义。", context: "这家公司通过偷天换日的方式修改合同条款，损害了消费者的合法权益。" },
  { idiom: "瓮中捉鳖", meaning: "比喻想要捕捉的对象已在掌握之中，手到擒来。强调对目标已形成绝对掌控、胜券在握，多用于形容抓捕、竞赛等场景中占尽优势。褒义或中性。", context: "警方已将整栋大楼团团包围，犯罪嫌疑人如同瓮中捉鳖，插翅难逃。" },
  { idiom: "敷衍了事", meaning: "指对事情马马虎虎、应付过去就算完事。强调做事态度不认真、责任心不强，只求表面过关，多用于批评工作作风不扎实。贬义。", context: "民生工程关系到群众切身利益，决不能敷衍了事，必须高标准高质量完成。" },
  { idiom: "虚与委蛇", meaning: "指对人虚情假意、敷衍应付，表面应酬而内心不诚。强调表面上热情附和，实际上并非真心，多用于形容人际交往中的敷衍态度。贬义或中性（视语境而定）。", context: "对于这些无理的指责，我方代表只得以礼相待、虚与委蛇，以争取更多斡旋空间。" },
  { idiom: "畏首畏尾", meaning: "指怕这怕那，瞻前顾后、顾虑太多。强调因胆小或顾虑过多而不敢放手做事，多用于批评做事犹豫不决、缺乏魄力。贬义。", context: "改革创新需要敢闯敢试的勇气，如果畏首畏尾，只会错失发展良机。" },
  { idiom: "闪烁其词", meaning: "指说话吞吞吐吐、躲躲闪闪，不肯透露真相或回避要害问题。强调言语含糊、不肯明说，多用于形容不愿正面回答问题的态度。贬义。", context: "面对记者的追问，发言人始终闪烁其词，不肯就核心问题作出明确回应。" },
  { idiom: "老生常谈", meaning: "原指老书生经常讲的话，现多指人们听惯了的、没有新意的老话。强调内容陈旧、缺乏新意，多用于形容言论或观点平淡无奇、毫无新意。贬义或中性（自谦时可用）。", context: "他的演讲虽不乏真知灼见，但开头那段关于勤奋的论述未免有些老生常谈。" },
  { idiom: "长篇大论", meaning: "指篇幅很长的文章或讲话。强调篇幅冗长、内容繁多，多用于形容文章或发言过长，有时含批评之意（指空话多、不精炼）。贬义或中性。", context: "他在会上一番长篇大论，说了近两个小时，却没有解决任何实际问题。" },
  { idiom: "陈词滥调", meaning: "指陈旧、空泛、不切实际的言论或文章。强调内容浮夸空洞、毫无新意且令人生厌，多用于批评没有创见、反复重复的老套言辞。贬义。", context: "这篇报告通篇都是陈词滥调，没有提出任何有价值的建议和措施。" },
  { idiom: "不痛不痒", meaning: "比喻不触及实质、不切中要害、无关痛痒。强调所说的话或所做的事浮于表面、没有实际作用，多用于批评言论或措施缺乏力度、流于形式。贬义。", context: "如果只是说一些不痛不痒的话，而不去真正解决问题，群众是不会满意的。" },
  { idiom: "隔靴搔痒", meaning: "比喻说话、做事不中肯、不贴切，没有抓住问题的关键，就像隔着靴子挠痒一样不起作用。强调抓不住要害、措施流于表面，无法真正解决问题。贬义。", context: "整改措施如果总是隔靴搔痒，不敢触及深层次矛盾，问题就永远得不到根治。" },
  { idiom: "大而化之", meaning: "原指使美德发扬光大、融会贯通，现多用来形容做事马虎、不认真，把问题笼统处理、不加细分。强调态度敷衍、方法粗放，多用于批评不细致、不严谨的作风。贬义。", context: "安全工作容不得大而化之，每一个细节都必须落到实处，否则就可能酿成大祸。" },
  { idiom: "浮光掠影", meaning: "比喻观察不细致、印象不深刻，像水面上的反光和一闪而过的影子。强调肤浅、不深入、匆匆而过，多用于形容学习、观察、体验等不够深入。贬义。", context: "旅游如果只是浮光掠影地走一遍，很难真正理解当地的文化内涵。" },
  { idiom: "张冠李戴", meaning: "把姓张的帽子戴到姓李的头上。比喻认错了对象或弄错了事实。强调因疏忽、误解而把此事物误作彼事物，将不同的身份、名称、事物等混淆。贬义或中性。", context: "报道中把两位不同领域科学家的成就张冠李戴，引发了读者的质疑。" },
  { idiom: "一步到位", meaning: "指一次就达到预定的目标或标准。强调省略中间环节、直接完成，多用于形容方案、措施、改革等一次性解决到位。中性或褒义（视语境而定）。", context: "改革不能急于求成，指望一步到位往往欲速则不达，需要循序渐进推进。" },
  { idiom: "一哄而上", meaning: "指很多人一下子拥上去，比喻不加冷静思考就盲目跟风、一拥而上。强调行动缺乏理性、盲目从众，多用于批评缺乏规划和判断的集体行为。贬义。", context: "看到直播带货火了，许多人一哄而上，结果由于缺乏经验和竞争力，很快就被市场淘汰。" },
  { idiom: "千篇一律", meaning: "指成千上万篇文章都是一个样，比喻办事或创作公式化、没有变化。强调缺乏个性、毫无新意、单调重复，多用于批评作品、建筑、方案等缺乏创新。贬义。", context: "城市建设不能千篇一律，每个地方都应保留自己的文化特色和历史记忆。" },
  { idiom: "整齐划一", meaning: "指非常有秩序、完全一致、协调统一。强调行动或外观高度一致、规范有序，多用于形容队列、服装、标准等。中性或褒义（视语境而定）。", context: "开幕式上，数百名演员动作整齐划一，展现了极强的团队协作能力。" },
  { idiom: "自然而然", meaning: "指不经外力干预，自由发展，自然如此。强调事物按照自身规律发展，没有人为的刻意干预，多用于形容结果或状态的顺理成章。中性或褒义。", context: "随着社会文明程度的提高，人们保护环境的意识也会自然而然地增强。" },
  { idiom: "顺理成章", meaning: "指写文章或做事顺着条理就能写好或做好，比喻随着某种情况的发展而自然产生的结果。强调合乎逻辑、顺其自然，多用于形容某事的发展合乎情理、自然形成。褒义。", context: "经济发展到一定阶段，文化产业崛起便顺理成章成为新的增长点。" },
  { idiom: "大势所趋", meaning: "指整个局势发展的必然趋向。强调历史潮流、社会发展的客观方向，非个人意志所能阻挡，多用于形容宏观趋势。中性。", context: "经济全球化是大势所趋，任何国家都无法逆潮流而动。" },
  { idiom: "水到渠成", meaning: "比喻条件成熟，事情自然会成功。强调不必强求，等到条件具备时结果自然达成，多用于形容功到自然成、顺其自然的结果。褒义。", context: "只要打好基础、积累经验，成功自然会水到渠成，不必急于求成。" },
  { idiom: "步步为营", meaning: "指军队每前进一步就设下一道营垒，比喻行动谨慎、稳扎稳打。强调每一步都很稳妥、不轻易冒险，多用于形容策略或战术。褒义。", context: "在市场竞争中，这家公司采取步步为营的策略，逐步扩大市场份额。" },
  { idiom: "行稳致远", meaning: "指稳扎稳打、循序渐进，才能走得长远。强调稳健行事、不急躁冒进，才能实现可持续发展，多用于形容发展战略、人生规划等。褒义。", context: "中国经济要实现高质量发展，必须坚持行稳致远的方针，防范各类风险。" },
  { idiom: "慎终如始", meaning: "指在事情结束时，也要像开始时那样谨慎小心。强调无论处于什么阶段都要保持初心和谨慎态度，始终如一，多用于形容做事有始有终、不松懈。褒义。", context: "安全生产必须慎终如始，任何时候都不能麻痹大意，任何时候都要绷紧安全这根弦。" },
  { idiom: "绵绵用力", meaning: "指持续不断地付出努力，不急于求成。强调长期坚持、持续发力、久久为功，多用于形容重大工程、长期战略或人才培养的持续推进。褒义。", context: "教育改革是一项系统工程，需要绵绵用力、久久为功，不能指望一蹴而就。" },
  { idiom: "孤注一掷", meaning: "指把所有的钱一次押上赌注，比喻在危急时用尽全部力量作最后一次冒险。强调不留余地、赌上所有，多用于形容绝境下的冒险行为。贬义。", context: "企业经营不能到了绝境才孤注一掷，平时就要做好风险防控，留足转圜空间。" },
  { idiom: "轻举妄动", meaning: "指未经慎重考虑而盲目行动。强调行动鲁莽、缺乏深思熟虑，多用于批评不经分析就贸然采取行动的行为。贬义。", context: "改革方案要经过充分论证才能实施，切不可轻举妄动，以免造成不可挽回的损失。" },
  { idiom: "刚愎自用", meaning: "指固执己见、不接受他人意见，自以为是。强调顽固任性、听不进不同意见，多用于形容性格或领导作风。贬义。", context: "一个领导者如果刚愎自用，听不进群众意见，迟早会犯错误。" },
  { idiom: "铤而走险", meaning: "指因走投无路而采取冒险行动。强调在迫不得已的情况下冒险做危险的事，多用于形容因生计所迫或处境绝望而走上险路。贬义。", context: "一些不法分子被暴利驱使，不惜铤而走险，从事非法经营活动。" },
  { idiom: "避实击虚", meaning: "指避开敌人的主力，攻击其薄弱环节。强调作战或竞争中巧妙选择突破口、避开强点打击弱点，多用于形容战术策略。褒义。", context: "在市场竞争中，这家企业采用避实击虚的策略，避开行业巨头的核心业务，从细分领域切入，迅速打开了局面。" },
  { idiom: "攻其不备", meaning: "指趁对方没有防备的时候突然发动攻击。强调利用对手的疏忽或意料之外进行打击，多用于战术、竞争等策略场景。褒义。", context: "特种部队攻其不备，在敌人毫无察觉的情况下成功突袭了敌方指挥部。" },
  { idiom: "先发制人", meaning: "指先于对手行动以取得主动权，制服对方。强调在对手行动之前抢先出手，占据有利态势，多用于形容主动出击的策略。褒义。", context: "在国际谈判中，我方代表团先发制人，提出了多项建设性议案，掌握了对话的主动权。" },
  { idiom: "视而不见", meaning: "指看见了却像没看见一样，形容对眼前的事物漠不关心或不加注意。强调主观上的忽视或冷漠，多用于批评对问题、现象等熟视无睹的态度。贬义。", context: "对于身边的不文明行为，我们不能视而不见，而应勇于劝导、共同维护公共环境。" },
  { idiom: "弃如敝履", meaning: "指像扔破鞋一样把它扔掉，比喻毫不可惜地抛弃。强调极度轻视、毫不留恋地丢弃，多用于形容对人或事物的鄙弃态度。贬义。", context: "这家企业成名后便弃如敝履般抛弃了当年一起打拼的合作伙伴，令人心寒。" },
  { idiom: "断章取义", meaning: "指不顾全篇文章或谈话的内容，孤立地取其中的一段或一句的意思，导致理解歪曲。强调片面截取、故意曲解原意，多用于批评不尊重原意的解读方式。贬义。", context: "个别媒体断章取义，截取了他讲话中的只言片语大肆炒作，完全歪曲了他的本意。" },
  { idiom: "束之高阁", meaning: "指把东西捆起来放在高高的架子上，比喻搁置不用或扔在一边不管。强调把有用的计划、建议、文件等放置一旁、不予采纳或推行。贬义。", context: "这些优秀的提案如果一直被束之高阁，不付诸实施，就失去了其应有的价值。" },
  { idiom: "鳞次栉比", meaning: "指像鱼鳞和梳子齿那样有次序地排列着。强调建筑物或船只等排列整齐、密集有序，多用于形容街道两旁房屋、码头船只等有序排列的景象。多用于具体排列物。褒义或中性。", context: "沿着江边望去，新建的高楼大厦鳞次栉比，蔚为壮观。" },
  { idiom: "大相径庭", meaning: "指彼此相差很远或矛盾很大。强调两者之间出入很大、明显不同，较“天壤之别”更强调方向或性质上的不一致。中性。", context: "两人的观点大相径庭，争论了半天谁也说服不了谁。" },
  { idiom: "别具一格", meaning: "指另有一种独特的风格。强调与众不同、独具特色，多用于形容建筑、艺术、作品等具有独特的风格或特色。褒义。", context: "这家餐厅的装修别具一格，融合了古典与现代的元素，吸引了许多食客前来打卡。" },
  { idiom: "各有千秋", meaning: "指各有各的存在价值，各有各的长处和特色。强调不同的人或事物各有所长、难分高下，多用于比较中肯定各自的独特价值。褒义。", context: "古典音乐与现代流行音乐各有千秋，前者深沉典雅，后者活力四射，都深受人们喜爱。" },
  { idiom: "绚丽多姿", meaning: "形容色彩灿烂、姿态多样，也比喻内容丰富、形式多样。强调色彩鲜艳、形态丰富，多用于形容景色、文化、生活等的多彩多姿。褒义。", context: "民族文化的花园里百花齐放、绚丽多姿，每一种文化都有其独特的魅力。" },
  { idiom: "移花接木", meaning: "指把花木的枝芽嫁接在另一株上，比喻暗中用手段更换人或事物。强调以隐蔽手段进行替换、偷换，多用于形容欺诈、作弊、偷梁换柱等行为。贬义。", context: "这家公司通过移花接木的方式，将劣质产品包装成知名品牌进行销售，严重侵害了消费者权益。" },
  { idiom: "釜底抽薪", meaning: "指从锅底抽掉柴火，比喻从根本上解决问题。强调从根源入手、彻底解决，多用于形容解决问题的根本性手段。褒义。", context: "治理城市内涝不能只靠临时抽水，必须釜底抽薪，从根本上完善地下管网系统。" },
  { idiom: "暗度陈仓", meaning: "指在公开行动背后隐藏真实意图，暗中进行另一项活动。强调明修栈道、暗度陈仓式的隐蔽行动，多用于形容军事、商业策略中的声东击西。褒义或中性。", context: "竞争对手表面上宣布退出市场，实则暗度陈仓，悄悄布局下一代产品的研发。" },
  { idiom: "反客为主", meaning: "指客人反过来成为主人，比喻变被动为主动、变次要为主导。强调通过策略将双方地位翻转，多用于形容谈判、竞争、局势变化中主客易位。褒义或中性。", context: "在谈判中，我方代表沉着应对，逐步掌握了主动权，最终成功反客为主，扭转了不利局面。" },
  { idiom: "彻头彻尾", meaning: "指从头到尾、完完全全、彻底。强调彻底性、完全性，多用于形容事物的性质、状态毫无保留，程度极重。中性或贬义（视语境而定）。", context: "这场变革是彻头彻尾的革命，从观念到制度都发生了根本性的转变。" },
  { idiom: "无声无息", meaning: "指没有声音和气息，比喻没有动静或影响，不被人察觉。强调不引人注意、悄无声息地发生或存在，多用于形容变化、行动等的隐蔽性。中性。", context: "春雨无声无息地滋润着大地，万物在不知不觉中焕发生机。" },
  { idiom: "潜移默化", meaning: "指人的思想或性格在不知不觉中受到感染、影响而发生了变化。强调在不知不觉中受到外界熏陶或影响，多用于形容环境、教育、文化等对人产生的长期、隐性的作用。褒义。", context: "良好的家风会在潜移默化中影响孩子的价值观，帮助他们形成健全的人格。" },
  { idiom: "浑然不觉", meaning: "指完全没有察觉到、毫无感觉。强调对周围事物的变化或自身状态毫无感知，多用于形容沉浸在某种状态中而对其他事物完全无感。中性。", context: "他读书读得入了迷，对窗外已经下起大雨浑然不觉。" },
  { idiom: "层出不穷", meaning: "指接连不断地出现，没有穷尽。强调数量多、连续不断、新事物源源涌现，多用于形容问题、现象、产品等。中性或褒义（视语境而定）。", context: "随着科技发展，智能家居新产品层出不穷，极大方便了人们的日常生活。" },
  { idiom: "屡见不鲜", meaning: "指经常看见，并不新奇。强调某事或某物出现次数多，已经不再令人感到新鲜，多用于形容常见现象或普遍存在的事物。中性。", context: "如今，大学生创业屡见不鲜，越来越多的年轻人选择在校园期间尝试自主创业。" },
  { idiom: "五花八门", meaning: "比喻花样繁多或变幻多端。强调种类繁多、形式多样，多用于形容商品、活动、手段等的丰富多样。中性或褒义。", context: "市场上各类促销活动五花八门，消费者在享受优惠的同时也需理性消费。" },
  { idiom: "应运而生", meaning: "指顺应时势而产生。强调在特定历史条件或时代背景下自然出现，多用于形容新事物、新产业、新现象在特定时期的兴起。褒义或中性。", context: "随着互联网的普及，直播带货等行业应运而生，成为新的经济增长点。" },
  { idiom: "独具慧眼", meaning: "指具有独特的眼光和见解，能够看到别人看不到的事物或本质。强调眼光独到、洞察力强，多用于形容在鉴赏、判断、选择等方面有超凡的见解和能力。褒义。", context: "这位收藏家独具慧眼，在别人都不看好的作品中发现了艺术价值，如今这些画作已价值连城。" },
  { idiom: "见微知著", meaning: "指看到微小的苗头，就能知道事物发展的显著变化或本质。强调从小处看到大局、从苗头预见到发展，多用于形容观察敏锐、善于从细节中把握规律。褒义。", context: "优秀的领导者往往能见微知著，从基层反馈的零星信息中捕捉到市场变化的先机。" },
  { idiom: "胸有成竹", meaning: "原指画竹子之前心中已有竹子的完整形象，后比喻做事之前已有周密的计划和把握。强调事前谋划充分、心中有数，多用于形容做事有把握、有准备。褒义。", context: "面对记者的提问，他胸有成竹，从容不迫地一一作答，显然对问题早有准备。" },
  { idiom: "未雨绸缪", meaning: "指趁着天还没下雨，就先修缮好房屋门窗，比喻事先做好准备工作。强调事前预防、提前准备，多用于形容有远见、防患于未然的意识和行动。褒义。", context: "防汛工作必须未雨绸缪，在雨季来临前就排查隐患、储备物资，确保万无一失。" },
  { idiom: "各自为政", meaning: "指各人按自己的主张办事，不互相配合。强调各行其是、缺乏统一协调，多用于形容部门、团队或组织之间缺乏协作、各自独立运作的状态。贬义。", context: "各部门如果各自为政，不仅效率低下，还容易造成资源浪费，必须加强统筹协调。" },
  { idiom: "为所欲为", meaning: "指想干什么就干什么，任意而为。强调毫无约束、任性妄为，多用于批评滥用权力或放纵行为。贬义。", context: "法治社会绝不允许任何人为所欲为，任何违法行为都将受到法律的制裁。" },
  { idiom: "画地为牢", meaning: "指在地上画个圈作为牢狱，比喻只许在指定的范围内活动。强调自我设限或被人为限制活动范围，多用于形容思维僵化、固步自封或受到不必要的束缚。贬义或中性。", context: "科研工作不能画地为牢，自我设限，而要勇于打破学科壁垒，开展跨界合作。" },
  { idiom: "越俎代庖", meaning: "指主祭的人跨过礼器去代替厨师做饭，比喻超越自己的职责范围去包办别人的事情。强调越权办事、多管闲事，多用于批评超越职权范围的行为。贬义。", context: "各部门应按职责分工开展工作，不能越俎代庖，干涉其他部门的正常业务。" },
  { idiom: "刻舟求剑", meaning: "指在船上刻记号以寻找掉入水中的剑，比喻拘泥成法、不知变通，用固定不变的观点看待变化发展的事物。强调无视事物变化、固守僵化，多用于批评做事不懂随机应变、脱离实际情况。贬义。", context: "面对不断变化的市场环境，企业如果还像刻舟求剑那样固守旧有的经营模式，注定会被淘汰。" },
  { idiom: "管中窥豹", meaning: "比喻只看到事物的一小部分，所见不全面或略有所得。强调观察角度狭窄、以偏概全，多用于批评仅凭局部现象就妄下结论。中性或略带贬义。", context: "仅凭个别数据就断定整个行业发展前景堪忧，无异于管中窥豹，难免失之偏颇。" },
  { idiom: "缘木求鱼", meaning: "指爬到树上去找鱼。比喻方向、方法不对，不可能达到目的。强调行事的方向或方法从根本上就错了，注定徒劳无功。贬义。", context: "在环保问题上，如果只追求经济利益而忽视生态保护，无异于缘木求鱼，最终只会得不偿失。" },
  { idiom: "大海捞针", meaning: "比喻在茫茫大海中寻找一根针，形容极难找到。强调寻找难度极大、范围广阔而目标极其微小，多用于形容搜寻或寻找极其困难的任务。中性。", context: "在浩如烟海的史料中找到那段历史的确切记载，简直就像大海捞针一样艰难。" },
  { idiom: "安于现状", meaning: "指对目前的情况感到满足，不思改变和进取。强调缺乏进取心、满足于现有状态而停滞不前，多用于批评不求上进的态度。贬义。", context: "在这个快速变化的时代，企业如果安于现状，不去主动拥抱变革，迟早会被市场所淘汰。" },
  { idiom: "固步自封", meaning: "指安于现状，不求进步，把自己限制在狭小的圈子里。强调自我封闭、拒绝接受新事物，多用于形容思想保守、拒绝创新。贬义。", context: "科学研究需要开放与交流，固步自封只会导致视野狭窄，无法取得真正的突破。" },
  { idiom: "裹足不前", meaning: "指因有所顾虑而停步不前，不敢前进。强调因担心困难或风险而不敢迈步，多用于形容面对挑战时的退缩状态。贬义。", context: "改革进入深水区后，不能因为遇到阻力就裹足不前，必须坚定决心、迎难而上。" },
  { idiom: "自暴自弃", meaning: "指自己甘于堕落，不求上进，放任自己。强调彻底放弃自我、丧失信心和斗志，多用于形容对人生或事业完全失去希望。贬义。", context: "人生难免有低谷，但不能因一时的失败就自暴自弃，要相信黑暗过后终有黎明。" },
  { idiom: "分身乏术", meaning: "指一个人忙得无法同时顾及几方面的事情。强调因精力或时间有限，难以兼顾多面，多用于形容事务繁忙、应接不暇的状态。中性或略带贬义。", context: "作为项目经理，他每天要处理大量事务，常常感到分身乏术，恨不得有分身术。" },
  { idiom: "事与愿违", meaning: "指事情的发展与自己的愿望相反。强调结果与初衷背道而驰、未能如愿，多用于形容努力后未能达成预期目标的情况。贬义或中性。", context: "他本想帮助朋友渡过难关，没想到事与愿违，反而给对方增加了更多的负担。" },
  { idiom: "措手不及", meaning: "指事出突然，来不及应付。强调毫无防备、应对仓促，多用于形容因缺乏准备而被打乱节奏的状态。贬义或中性。", context: "洪水来得太快，村民们措手不及，所幸在救援人员的帮助下及时转移到了安全地带。" },
  { idiom: "适得其反", meaning: "指恰恰得到与预期相反的结果。强调结果与目的完全相反、背离初衷，多用于形容方法不对或用力过猛导致的不良后果。贬义。", context: "教育孩子时一味严厉批评，可能会适得其反，让孩子产生逆反心理。" },
  { idiom: "常备不懈", meaning: "指时刻准备着，从不松懈防备。强调长期保持戒备状态、毫不放松，多用于形容军事、安全、应急等领域的高度警觉。褒义。", context: "边防战士常备不懈，日夜守护着祖国的边疆安全。" },
  { idiom: "如履薄冰", meaning: "比喻行事极为谨慎，存有戒心。强调小心翼翼、生怕出错的心理状态，多用于形容在危险或重要局面下的审慎态度。中性（多用于谨慎语境）。", context: "安全生产责任重大，相关管理人员时刻如履薄冰，不敢有丝毫懈怠。" },
  { idiom: "严阵以待", meaning: "指摆好严整的阵势，等待来犯的敌人。强调做好了充分的准备，等待挑战或敌人的到来，多用于形容全面戒备、准备迎战的状态。褒义。", context: "防汛指挥部已启动一级响应，抢险队伍严阵以待，随时准备应对可能出现的险情。" },
  { idiom: "谨小慎微", meaning: "指对细小的事情也过分小心谨慎，做事缩手缩脚。强调过分小心、不敢放开手脚，多用于形容过度谨慎甚至胆怯的态度。贬义或中性（视语境而定）。", context: "改革需要敢闯敢试的魄力，如果总是谨小慎微，就难以取得突破性进展。" },
  { idiom: "一丝不苟", meaning: "形容做事认真细致，一点儿不马虎。强调态度严谨、注重细节，多用于形容工作作风或治学态度。褒义。", context: "航天工程不容有任何差错，每一个螺丝钉的安装都必须一丝不苟。" },
  { idiom: "寸步不让", meaning: "指在谈判、争论或竞争中丝毫不肯让步或退却。强调立场坚定、坚决不退让，多用于形容在原则问题或利益争夺上的强硬态度。褒义或中性。", context: "在领土主权问题上，中国寸步不让，坚决维护国家核心利益。" },
  { idiom: "锱铢必较", meaning: "指对极少的钱或细小的事都计较得很清楚。强调计较细小得失、过分看重微小利益，多用于批评气量狭小、过于看重蝇头小利。贬义。", context: "合作中如果总是锱铢必较，盯着眼前小利不放，就难以建立长久的信任关系。" },
  { idiom: "壁垒分明", meaning: "指界限非常清楚、截然分明。强调两个事物之间的界线清晰、互不混淆，多用于形容立场、观点、阵营等的鲜明对立。中性或褒义。", context: "在辩论赛上，正反双方观点壁垒分明，争论十分激烈。" },
  { idiom: "寅吃卯粮", meaning: "指寅年吃了卯年的粮食，比喻经济困难，预先透支未来的收入。强调提前消耗未来的资源、入不敷出，多用于形容财政困难或资源透支。贬义。", context: "这种靠借债维持运转的做法无异于寅吃卯粮，长此以往必将陷入更深的财务危机。" },
  { idiom: "一厢情愿", meaning: "指单方面的愿望，不考虑对方是否同意或客观情况是否允许。强调主观上认为可行而客观上不切实际，多用于批评脱离实际的想法。贬义。", context: "他认为只要降价就能赢得市场，这不过是一厢情愿，产品质量才是关键。" },
  { idiom: "朝令夕改", meaning: "指早晨发布的命令，晚上就改了。形容政策、主张等频繁变动、不稳定。强调缺乏连贯性、反复无常，多用于批评政策或决定变化过快、令人无所适从。贬义。", context: "一项政策如果总是朝令夕改，不仅会让基层执行者无所适从，也会损害政府的公信力。" },
  { idiom: "好高骛远", meaning: "指不切实际地追求过高过远的目标。强调脱离自身实际、眼高手低，多用于批评不踏实的态度。贬义。", context: "年轻人要有理想，但不能好高骛远，要一步一个脚印地努力。" },
  { idiom: "以退为进", meaning: "指以退让作为前进的手段，通过暂时后退来更好地前进。强调表面上退让、实际上为下一步进攻做准备，多用于形容谈判、竞争等策略。褒义。", context: "谈判中有时需要以退为进，在次要问题上适当让步，以换取在核心利益上的主动权。" },
  { idiom: "以柔克刚", meaning: "指用柔韧的力量去战胜刚强的力量，比喻用温和、灵活的方式应对强硬、刚烈的对手。强调以柔制刚、四两拨千斤，多用于形容处理矛盾或冲突的智慧。褒义。", context: "处理群众矛盾时，基层干部要学会以柔克刚，用耐心和智慧化解纠纷，而不是硬碰硬。" },
  { idiom: "以虚为实", meaning: "指把虚假的当作真实的，也形容在策略中以假象迷惑对手。强调虚实结合、真假难辨，多用于军事、竞争等战术场景。褒义或中性。", context: "在军事演习中，指挥员运用以虚为实的战术，用假目标迷惑对方侦察系统，成功掩护了主力部队的调动。" },
  { idiom: "犹豫不决", meaning: "指拿不定主意，下不了决心。强调面对选择时内心摇摆、无法果断决断，多用于形容优柔寡断的状态。贬义或中性。", context: "机会稍纵即逝，如果总是犹豫不决，就可能在竞争中失去先机。" },
  { idiom: "左顾右盼", meaning: "指向左右两边看，形容犹豫不决、观望等待的样子。强调瞻前顾后、不敢果断行事，多用于形容做事不够坚决、反复观望。贬义。", context: "创业需要果断的决策力，如果总是左顾右盼，犹豫不前，再好的机遇也会擦肩而过。" },
  { idiom: "举棋不定", meaning: "指下棋时拿着棋子不知该走哪一步，比喻做事拿不定主意、犹豫不决。强调因考虑过多而无法做出抉择，多用于形容面临重要决策时的犹豫心态。贬义或中性。", context: "在重大投资项目面前，管理层举棋不定，反复讨论数月仍未达成一致意见。" },
  { idiom: "见风使舵", meaning: "指看风向转舵，比喻看形势或别人的眼色行事。强调见机行事、随机应变，但多含贬义，指没有原则、趋炎附势、随风倒。贬义。", context: "这种见风使舵、见人说人话见鬼说鬼话的做法，最终会让人失去信任。" },
  { idiom: "泥古不化", meaning: "指拘泥于古代的成规或学说，不知变通。强调死守旧章、拒绝接受新事物或新变化，多用于批评思想僵化、固守陈规的态度。贬义。", context: "历史研究需要创新思维，如果泥古不化，只会停留在对典籍的机械解读上，无法产生新的学术成果。" },
  { idiom: "听之任之", meaning: "指对事情放任自流，不加约束，不过问、不干预。强调消极放任、不采取任何行动，多用于批评对不良现象放任不管的态度。贬义。", context: "对于违规排污行为绝不能听之任之，必须依法严肃查处。" },
  { idiom: "自作主张", meaning: "指不请示上级或不与别人商量，按照自己的意见擅自做主处理事情。强调独断专行、不经商议便自行决定，多用于批评擅自做主的行为。贬义或中性（视语境而定）。", context: "他未经请示便自作主张调整了项目方案，虽然最终效果不错，但越权行为仍不值得提倡。" },
  { idiom: "照猫画虎", meaning: "比喻照着样子模仿，只求形似而不得要领。强调生硬模仿、缺乏创造，多用于批评脱离实际、照搬他人做法而不求甚解的行为。贬义。", context: "学习先进经验不能照猫画虎，机械照搬，而要结合本地实际，因地制宜地加以转化运用。" },
  { idiom: "拾人牙慧", meaning: "指拾取别人的只言片语当作自己的话，比喻抄袭或套用别人的言论。强调毫无创见、只会重复别人的旧话，多用于批评缺乏独立思考的言论或文章。贬义。", context: "学术研究要有独立见解，不能拾人牙慧，一味重复前人的观点而毫无创新。" },
  { idiom: "随波逐流", meaning: "指随着波浪起伏、跟着水流漂荡，比喻没有主见，随大流。强调缺乏独立判断、盲目跟随他人或潮流，多用于批评缺乏原则性和独立思考。贬义。", context: "在信息纷繁复杂的时代，青年人要善于独立思考，不能随波逐流，人云亦云。" },
  { idiom: "厚积薄发", meaning: "指充分地积累，少量地释放。比喻经过长期充分的准备和积累，然后从容地发挥出来。强调先积累后释放、厚实根基的重要性，多用于形容学问、能力、事业等。褒义。", context: "科学研究需要厚积薄发，只有扎实打好基础，才能取得突破性成果。" },
  { idiom: "谋定后动", meaning: "指谋划准确周到之后再采取行动。强调先策划、后行动，不打无准备之仗，多用于形容办事稳健、深思熟虑的策略。褒义。", context: "重大决策必须谋定后动，在充分调研论证的基础上稳步推进。" },
  { idiom: "有备无患", meaning: "指事先有准备，就可以避免祸患。强调预防为主、事前准备能够减少风险，多用于形容防患于未然的意识。褒义。", context: "防汛工作要做到有备无患，宁可备而不用，不可用时无备。" },
  { idiom: "集思广益", meaning: "指集中众人的智慧，广泛吸收有益的意见。强调博采众长、汇集多方智慧，多用于形容决策或研究中的民主协商。褒义。", context: "制定政策要充分集思广益，广泛听取各方面专家和群众的意见，确保决策科学合理。" },
  { idiom: "因噎废食", meaning: "比喻因为怕出问题而索性不干该干的事。强调因小失大、因为害怕小风险而放弃正常活动，多用于批评过度谨慎的行为。贬义。", context: "不能因为少数企业违规就全面叫停整个行业，这种做法无异于因噎废食。" },
  { idiom: "矫枉过正", meaning: "指纠正偏差或错误而超过了应有的限度，反而陷入另一种偏差。强调过度纠正、从一个极端走向另一个极端。贬义。", context: "治理市场乱象要把握好度，避免矫枉过正，影响正常的经济活动。" },
  { idiom: "半途而废", meaning: "指事情做到一半就停止，不能坚持到底。强调缺乏恒心、中途放弃，多用于批评做事有始无终的行为。贬义。", context: "学习任何一门技能都需要持之以恒的精神，半途而废终究一事无成。" },
  { idiom: "瞻前顾后", meaning: "指顾虑太多、犹豫不决，也指兼顾前后、考虑周全。强调因担心风险而迟迟不敢行动（多用于贬义），也可指周密考虑（中性）。以否定形式“瞻前顾后、畏首畏尾”常见。", context: "改革需要敢闯敢试的精神，如果总是瞻前顾后、患得患失，就会错失发展良机。" },
  { idiom: "颠扑不破", meaning: "指无论怎样摔打都不破裂，比喻言论、理论等十分正确，无法被推翻。强调真理或道理的坚固性、不可动摇性。褒义。", context: "马克思主义是颠扑不破的真理，指引着中国革命和建设不断取得胜利。" },
  { idiom: "显而易见", meaning: "指事情或道理非常明显，容易看清楚。强调表现上清晰可见、一目了然，多用于形容事实或现象的明显程度。中性或褒义。", context: "保护生态环境的重要性显而易见，这关系着子孙后代的生存与发展。" },
  { idiom: "众所周知", meaning: "指大家普遍知道，人人尽知。强调知晓范围极广、人人皆知，多用于形容常识性、公知性的事实或信息。中性。", context: "中国是一个拥有五千年文明历史的国家，这一点众所周知。" },
  { idiom: "毋庸置疑", meaning: "指事实明显或理由充分，不必怀疑。强调结论确定无疑、无需质疑，语气坚定，多用于强调事实的确定性和不可置疑性。褒义或中性。", context: "中国共产党的领导是中国特色社会主义最本质的特征，这一点毋庸置疑。" },
  { idiom: "后患无穷", meaning: "指今后的祸害没有穷尽。强调当前行为或决策会留下长期负面影响，难以消除，多用于形容短视行为或不当处置带来的严重后果。贬义。", context: "如果对食品安全问题睁一只眼闭一只眼，必将后患无穷，损害整个行业的信誉。" },
  { idiom: "一无所有", meaning: "指什么都没有，形容极度贫穷或彻底丧失。强调空无、毫无所有，多用于形容物质匮乏或精神空虚。中性或贬义。", context: "面对一贫如洗的家境，他并非一无所有，至少还有改变命运的勇气和梦想。" },
  { idiom: "贻笑大方", meaning: "指被行家或内行人笑话。强调因言行拙劣或见识浅薄而让专业人士见笑，多用于自谦或批评不专业的行为。贬义（自谦时可表谦逊）。", context: "在这位资深学者面前谈古论今，无异于班门弄斧，恐怕会贻笑大方。" },
  { idiom: "望梅止渴", meaning: "原指曹操用前方有梅林来缓解士兵口渴，后比喻用空想来安慰自己。强调以虚幻的想象来满足现实需求，多用于批评自我安慰、不解决问题的做法。贬义。", context: "如果只停留在口头承诺上，不拿出实际举措，无异于望梅止渴，群众是不会满意的。" },
  { idiom: "坐井观天", meaning: "比喻眼界狭小、见识短浅，像坐在井底的青蛙只能看到井口那么大的一片天。强调视野狭窄、缺乏对广阔世界的认知，多用于批评目光短浅、自以为是。贬义。", context: "年轻人要走出课堂、走向社会，开阔视野，切莫坐井观天，满足于书本上的有限知识。" },
  { idiom: "推陈出新", meaning: "指去掉旧事物的糟粕，取其精华，并使其向新的方向发展。强调在继承的基础上创新、革故鼎新，多用于形容文化、艺术、技术等领域的创新发展。褒义。", context: "传统文化要在推陈出新中焕发活力，既保留精髓，又融入时代元素。" },
  { idiom: "大展拳脚", meaning: "指充分施展自己的才能和本领。强调在合适的平台或时机下尽情发挥潜力，多用于形容人才在宽广舞台上施展才华。褒义。", context: "青年人才要到基层一线去大展拳脚，在实干中锤炼本领、实现价值。" },
  { idiom: "敢为人先", meaning: "指敢于走在前面、做别人没有做过的事。强调勇于创新、敢于尝试新事物，多用于形容具有开创精神和魄力。褒义。", context: "深圳特区以敢为人先的精神，创造了举世瞩目的发展奇迹。" },
  { idiom: "踔厉奋发", meaning: "指精神振奋、斗志昂扬，奋发向前。强调意气风发、勇往直前的精神状态，多用于形容在新时代新征程上奋发有为。褒义。", context: "新时代青年要踔厉奋发、笃行不怠，在实现民族复兴的赛道上奋勇争先。" },
  { idiom: "故弄玄虚", meaning: "指故意玩弄花招，使人迷惑，难以捉摸。强调有意制造神秘感或模糊性来迷惑他人，多用于批评故装高深、故作风雅的行为。贬义。", context: "真正有学问的人从不故弄玄虚，而是力求把深奥的道理讲得通俗易懂。" },
  { idiom: "照本宣科", meaning: "指照着本子念条文，比喻死板地照现成的文字或讲稿宣读，不能灵活运用。强调机械呆板、缺乏灵活性和创造性，多用于批评讲课或发言照抄照搬、缺乏发挥。贬义。", context: "课堂教学不能满足于照本宣科，教师要引导学生主动思考，而不是一味灌输。" },
  { idiom: "人云亦云", meaning: "指人家怎么说，自己也跟着怎么说，没有独立见解。强调缺乏主见、盲目附和别人的言论，多用于批评缺乏独立思考能力的从众行为。贬义。", context: "面对各种观点，我们要有自己的判断，不能人云亦云，盲目跟风。" },
  { idiom: "装腔作势", meaning: "指故意做作，装出某种姿态或架势来引人注意或吓唬人。强调刻意做作、故作姿态，多用于批评虚伪、不自然的行为。贬义。", context: "真正的艺术家从不装腔作势，而是用真诚的作品打动观众。" },
  { idiom: "无病呻吟", meaning: "比喻没有值得忧伤的事情却故意唉声叹气，也比喻文艺作品缺乏真情实感、矫揉造作。强调矫情造作、缺乏真实感受，多用于批评虚假煽情或小题大做。贬义。", context: "有些文章内容空洞、矫揉造作，不过是无病呻吟，读来令人乏味。" },
  { idiom: "言不由衷", meaning: "指说的话不是发自内心的，心口不一。强调说话时内心真实想法与表达内容不一致，多用于批评虚伪、不坦诚的表达。贬义。", context: "他在公开场合的发言看似慷慨激昂，实则言不由衷，并未真正认同这项政策。" },
  { idiom: "冠冕堂皇", meaning: "形容表面上庄严体面、光明正大的样子，实际未必如此。强调表面堂皇而实质未必相符，多含贬义，用于批评表面光鲜实则虚伪的言行。贬义。", context: "他找了一堆冠冕堂皇的理由来推卸责任，实际上不过是为了掩饰自己的失职。" },
  { idiom: "深入浅出", meaning: "指用浅显易懂的语言或方式表达深奥的道理。强调内容深刻但表达通俗易懂，多用于形容讲解、写作、教学等方面的出色能力。褒义。", context: "这位教授讲课深入浅出，把复杂的哲学理论讲得通俗易懂，深受学生欢迎。" },
  { idiom: "举一反三", meaning: "指从一件事情类推而知道许多事情，形容善于推理、触类旁通。强调善于类比推理、由此及彼，多用于形容学习能力强、善于触类旁通。褒义。", context: "学习方法比知识本身更重要，学会举一反三，就能在有限的知识中生出无限的智慧。" },
  { idiom: "言简意赅", meaning: "指语言简练而意思完备。强调表达简洁明了而不失丰富内涵，多用于形容文章或言辞精炼准确。褒义。", context: "他的总结言简意赅，用短短几句话就把复杂的项目情况说得一清二楚。" },
  { idiom: "雾里看花", meaning: "比喻看事情不真切、不清晰。强调观察模糊、认识不清、难辨真相，多用于形容对复杂事物的认知状态。中性或略带贬义。", context: "这些政策文件专业性很强，普通群众往往如雾里看花，难以理解其真正含义。" },
  { idiom: "异想天开", meaning: "比喻想法非常离奇、不切实际。强调想法奇特、脱离现实，多用于形容不切实际的幻想或过于大胆的设想。贬义或中性（自嘲时可表大胆想象）。", context: "在缺乏基础研究支撑的情况下，想直接实现技术突破无异于异想天开。" },
  { idiom: "无从下手", meaning: "指面对事情不知从哪里开始着手处理。强调面对复杂问题时找不到切入点、不知如何开始，多用于形容面对难题时的迷茫状态。中性或略带贬义。", context: "面对堆积如山的原始数据，新来的研究员一时无从下手，幸好有老同事耐心指导。" },
  { idiom: "毫发无伤", meaning: "指毫毛和头发都没有受到损伤，形容毫无损伤。强调极度安全、没有受到任何伤害或损失，多用于形容在危险或变故中安然无恙。褒义或中性。", context: "尽管地震震感强烈，但全村村民及时撤离，最终毫发无伤，无一人伤亡。" },
  { idiom: "严丝合缝", meaning: "指缝隙严密闭合，形容衔接得非常紧密、毫无间隙。强调结合紧密、精确吻合，多用于形容工艺、对接、配合等方面的完美契合。褒义。", context: "榫卯结构的每一处接合都严丝合缝，不用一根钉子却坚固异常，体现了古代工匠的高超智慧。" },
  { idiom: "轻而易举", meaning: "形容事情非常容易做，毫不费力。强调操作简单、不费力气，多用于形容完成某项任务的轻松程度。中性或褒义。", context: "在经验丰富的老师傅手中，这门复杂的工艺做起来轻而易举，但初学者往往要花很长时间才能掌握。" },
  { idiom: "完好无损", meaning: "指完整无缺、没有受到任何损害。强调物品或事物保持原始状态、毫无损坏，多用于形容文物、物品等保存或经受考验后的状态。褒义或中性。", context: "这批出土的青铜器在地下埋藏了三千多年，依然完好无损，令人惊叹。" },
  { idiom: "源远流长", meaning: "指河流的源头很远，水流很长，比喻历史久远、根底深厚。强调时间长、渊源深、传承久，多用于形容文化、传统、友谊等具有深厚历史积淀的事物。褒义。", context: "中华文明源远流长，五千年的灿烂文化是中华民族的根和魂。" },
  { idiom: "一枝独秀", meaning: "比喻在同类事物中最为突出优秀。强调独占鳌头、远超其他，多用于形容在众多竞争者中表现最为出色。褒义。", context: "在全球经济低迷的背景下，中国经济一枝独秀，展现出强大韧性。" },
  { idiom: "一以贯之", meaning: "指用一种思想、原则贯穿始终。强调前后一致、保持不变的连贯性，多用于形容理论、政策、作风的持续一致。褒义。", context: "为人民服务的宗旨，我们党一以贯之，从未改变。" },
  { idiom: "标新立异", meaning: "指提出新奇的主张，表示与众不同。强调刻意与众不同、追求新奇，多含贬义，指故意显示与众不同以引人注意，也可中性形容创新。贬义或中性（视语境而定）。", context: "企业文化不应只是标新立异的口号，而应真正内化于心、外化于行。" },
  { idiom: "扬长避短", meaning: "指发扬长处，避开短处。强调在行事过程中充分发挥自身优势、规避劣势，多用于形容策略、方法、竞争中的明智选择。褒义。", context: "乡村振兴要因地制宜、扬长避短，充分利用当地的自然禀赋和特色资源。" },
  { idiom: "顺水推舟", meaning: "比喻顺着情势的发展趋势行事，不强行逆转。强调顺应形势、借势而为，多用于形容处事灵活、善于利用现有条件。中性或褒义。", context: "既然市场已经形成了这个消费趋势，我们不妨顺水推舟，顺势推出相关产品。" },
  { idiom: "因陋就简", meaning: "指就着原有的简陋条件办事，不强求完备。强调在条件有限的情况下因地制宜、务实操作，不追求奢华或完备。中性（可表务实，也可批评凑合）。", context: "在经费有限的情况下，团队因陋就简，利用现有设备完成了前期实验。" },
  { idiom: "另辟蹊径", meaning: "指另外开辟一条路，比喻另创一种风格或方法。强调跳出常规思维、不走寻常路，寻找新的解决方案或途径。褒义。", context: "面对传统市场的饱和，这家企业另辟蹊径，开拓了全新的细分领域。" },
  { idiom: "尾大不掉", meaning: "原指尾巴太大，摆动不起来，现比喻机构庞大、下属势力过大，使上级指挥不灵。强调因机构臃肿或下属力量过强而难以有效控制，多用于形容组织管理中的失控局面。贬义。", context: "公司层级过多、部门臃肿，已经出现了尾大不掉的迹象，急需精简机构、优化管理。" },
  { idiom: "阳奉阴违", meaning: "指表面上遵从，暗地里违背。强调表面一套、背后一套，口是心非，多用于批评当面顺从、背后搞小动作的虚伪行为。贬义。", context: "对于上级的决策部署，必须坚决执行，绝不允许阳奉阴违、打折扣、搞变通。" },
  { idiom: "分崩离析", meaning: "形容国家、集团、家庭等分裂瓦解，无法维持统一。强调整体被破坏、离散崩溃，多用于形容组织、团队等因内部矛盾而走向瓦解。贬义。", context: "历史上许多庞大帝国因内部矛盾而分崩离析，最终走向灭亡。" },
  { idiom: "南辕北辙", meaning: "指心里想着往南走，却驾车向北行。比喻行动与目标完全相反，背道而驰。强调目标和行动之间的反向对立，多用于形容方向性错误。贬义。", context: "他的想法和实际做法南辕北辙，结果离目标越来越远。" },
  { idiom: "众志成城", meaning: "比喻大家团结一致，力量无比强大，像坚固的城墙一样不可摧毁。强调齐心协力、凝聚力量战胜困难，多用于形容集体奋斗的磅礴力量。褒义。", context: "面对突如其来的洪水，军民众志成城，筑起了保卫家园的钢铁长城。" },
  { idiom: "同仇敌忾", meaning: "指大家一致地对敌人抱着仇恨和愤怒，共同抗击敌人。强调面对共同敌人时的团结一致、同仇敌忾，多用于形容战争或斗争中的集体意志。褒义。", context: "抗战时期，中华儿女同仇敌忾，用血肉之躯筑起了民族独立的万里长城。" },
  { idiom: "群策群力", meaning: "指集中众人的智慧和力量，大家共同出谋划策、贡献力量。强调汇聚集体的智慧与力量协同行动，多用于形容团队协作、民主决策。褒义。", context: "项目成功得益于团队群策群力，每个人都贡献了自己的专业所长。" },
  { idiom: "和衷共济", meaning: "指大家一条心，共同克服困难。强调同心协力、团结互助，多用于形容在困境中携手合作、共渡难关。褒义。", context: "面对疫情挑战，全国人民和衷共济，筑起了抗击疫情的坚固防线。" },
  { idiom: "腹背受敌", meaning: "指前后都受到敌人的攻击，形容处于两面受敌的困境。强调同时遭受来自前方和后方的夹击，多用于形容军事或竞争中的不利局面。贬义。", context: "这支队伍在战场上腹背受敌，陷入了极其被动的局面，急需援军支援。" },
  { idiom: "孤掌难鸣", meaning: "比喻一个人力量有限，难以单独完成事情。强调缺乏协助、孤立无援，多用于形容在缺乏支持的情况下难以成事。中性或略带贬义。", context: "环保事业需要全社会共同努力，仅靠一个部门孤掌难鸣，无法真正奏效。" },
  { idiom: "各自为战", meaning: "指各自独立作战，不互相配合。强调缺乏统一指挥和协同配合，各自孤立行动，多用于形容团队或部门之间缺乏协作、各行其是的状态。贬义。", context: "如果各部门还是各自为战，不肯共享信息，就很难形成合力应对这场危机。" },
  { idiom: "形单影只", meaning: "形容孤独一人，没有同伴。强调孤单、无依无靠的个体状态，多用于形容人的孤独处境或形影相吊的萧索感。中性或略带贬义。", context: "夕阳下，老人形单影只地坐在长椅上，望着远方，像是在等待远方的子女归来。" },
  { idiom: "故步自封", meaning: "指安于现状，不求进步，把自己限制在狭小的圈子里。强调自我封闭、拒绝接受新事物，多用于形容思想保守、拒绝创新。贬义。【注：“故步自封”与“固步自封”义近，可通用。】", context: "科学研究需要开放与交流，故步自封只会导致视野狭窄，无法取得真正的突破。" },
  { idiom: "单打独斗", meaning: "指单独一人进行争斗，不依靠他人或团体的力量。强调孤立行动、缺乏合作，多用于形容做事不依靠团队、独力支撑的状态。中性或略带贬义。", context: "面对复杂多变的全球市场，企业不能再单打独斗，而应善于整合资源、寻求合作共赢。" },
  { idiom: "喜闻乐见", meaning: "指喜欢听、乐意看，形容非常受欢迎。强调事物受到大众的普遍喜爱和欢迎，多用于形容文艺作品、节目、活动等广受欢迎。褒义。", context: "要让社会主义核心价值观通过群众喜闻乐见的形式传播开来，真正入脑入心。" },
  { idiom: "翘首以盼", meaning: "指抬起头来殷切地盼望，形容非常期待。强调急切地等待、充满期待，多用于形容人们对好消息、佳音、盛事等的热烈期盼。褒义。", context: "春节临近，远在他乡的游子翘首以盼归家的列车。" },
  { idiom: "津津乐道", meaning: "指很有兴趣地说个不停。强调饶有兴趣、乐此不疲地谈论某事，多用于形容人们对感兴趣的话题、故事、成就等的热烈讨论。褒义。", context: "老人们对那段激情燃烧的岁月津津乐道，讲起来滔滔不绝。" },
  { idiom: "望眼欲穿", meaning: "指眼睛都要望穿了，形容盼望得非常急切。强调极度迫切的期待和渴望，多用于形容对亲人归回、音讯到达等事的殷切盼望。褒义。", context: "母亲站在村口，望眼欲穿地等待着远行多年的儿子归来。" },
  { idiom: "手忙脚乱", meaning: "形容做事慌张、忙乱无序。强调因时间紧、任务多而动作慌乱、缺乏条理，多用于形容忙碌中的狼狈状态。贬义。", context: "第一次上直播，她手忙脚乱，不是忘词就是点错按钮，好在观众很包容。" },
  { idiom: "拖泥带水", meaning: "比喻说话或做事不干脆、不痛快，拖拖拉拉。强调做事动作迟疑、拖沓，或说话啰嗦不干脆，多用于批评不果断、不利落的行为。贬义。", context: "处理紧急事务时，最忌讳拖泥带水，必须果断决策、迅速行动。" },
  { idiom: "嘘寒问暖", meaning: "指关切地问候人的冷暖，形容对他人生活起居的关心和体贴。强调细致的关怀与问候，多用于形容对他人的关心、照顾。褒义。", context: "社区工作者经常上门嘘寒问暖，为独居老人送去温暖和关怀。" },
  { idiom: "排忧解难", meaning: "指为他人排除忧愁、解除困难。强调主动帮助他人解决实际困难，多用于形容热心助人的行为。褒义。", context: "基层干部要真心实意为群众排忧解难，把群众的急难愁盼放在心上。" },
  { idiom: "雪中送炭", meaning: "比喻在别人急需帮助时给予支持和援助。强调在对方最困难的时候及时伸出援手，多用于形容救急济困的善举。褒义。", context: "在最困难的时候，是乡亲们雪中送炭，帮我们渡过了难关，这份情谊永远记在心里。" },
  { idiom: "保驾护航", meaning: "指保护航行，比喻为某事提供保护和保障，使其顺利进行。强调为重要事务提供安全、稳定的保障，多用于形容政策、制度、力量等为发展保驾护航。褒义。", context: "完善的法治环境为民营经济健康发展保驾护航，让企业家安心创业。" },
  { idiom: "熟视无睹", meaning: "指对经常看到的事物看惯了，就像没有看见一样。强调对身边常见事物或问题的忽视与漠然，多用于批评因习惯而失去敏感性的态度。贬义。", context: "面对街头乱贴的小广告，我们不能熟视无睹，要积极参与城市治理，共同维护市容环境。" },
  { idiom: "置若罔闻", meaning: "指放在一边不管，好像没听见一样。强调对他人的劝告、意见或警示完全不理睬、不重视，多用于批评对正确意见或警告的漠视态度。贬义。", context: "对于群众的合理诉求，相关部门不能置若罔闻，必须认真对待、及时回应。" },
  { idiom: "充耳不闻", meaning: "指塞住耳朵不听，形容故意不听别人的话或意见。强调有意地拒绝听取他人的意见或劝告，多用于批评固执己见、不愿接受批评的态度。贬义。", context: "多次提醒他注意安全，他却充耳不闻，最终酿成了事故，后悔莫及。" },
  { idiom: "退避三舍", meaning: "指主动退让九十里，比喻退让和回避，避免冲突。强调了为避免冲突或不愿与对方较量而主动回避、退让，多用于形容谦让或策略性回避。中性或褒义（视语境而定）。", context: "面对无端的指责，他选择了退避三舍，不与对方纠缠，用沉默维护了自己的尊严。" },
  { idiom: "环环相扣", meaning: "指一环扣一环，形容彼此紧密连接，无法分开。强调各个部分之间衔接紧密、相互依存，多用于形容逻辑、工序、情节等环节之间的紧密联系。褒义或中性。", context: "整个生产流程环环相扣，任何一个环节出问题都会影响最终产品的质量。" },
  { idiom: "周而复始", meaning: "指一圈又一圈地循环，形容不断循环往复。强调事物按照一定的规律不断循环、周而复始，多用于形容季节更替、生命轮回等自然规律。中性。", context: "四季周而复始，春去秋来，大地在循环中孕育着新的生机。" },
  { idiom: "绵绵不绝", meaning: "连续不断的样子。多形容雨、血脉、香火、情感等抽象事物的延续，强调持久且不间断。褒义或中性。", context: "红色基因绵绵不绝，融入一代代青年的血脉之中。" },
  { idiom: "循环往复", meaning: "指事物反复出现、不断循环。强调反复出现、生生不息，多用于形容规律性的重复过程。中性。", context: "自然界的水资源通过蒸发、降水和径流循环往复，维持着生态系统的平衡。" },
  { idiom: "背道而驰", meaning: "朝着相反的方向奔跑，比喻行动方向与目标完全相反，或与正确的方向相违背。强调方向性对立、行为与初衷完全相反。贬义。", context: "这种做法与可持续发展的理念背道而驰，必须立即纠正。" },
  { idiom: "截然不同", meaning: "指两种事物毫无共同之处，完全不一样。强调彻底不同、没有任何相似之处，多用于形容本质上的差异。中性。", context: "南北方的饮食习惯截然不同，南方偏爱米饭，北方则以面食为主。" },
  { idiom: "天差地别", meaning: "指相差极大，如天和地的差别一样。强调差距极为悬殊、不可同日而语，多用于形容程度或水平上的巨大落差。中性。", context: "改革开放前后，人民的生活水平可谓天差地别，发生了翻天覆地的变化。" },
  { idiom: "功亏一篑", meaning: "指筑一座九仞高的土山，因只差一筐土而未能完成，比喻做事因差最后一点努力而未能成功。强调因最后的疏忽或放松导致前功尽弃，多用于惋惜差一步就能成功却未能圆满。贬义或中性。", context: "这项工程历时三年，却在最后验收阶段因细节问题功亏一篑，令人惋惜。" },
  { idiom: "水土不服", meaning: "指因不适应异地气候、饮食等而身体不适，也比喻对新环境不适应。强调对异乡环境的不适应，多用于形容初到陌生地方时身体或心理的不适应状态。中性或略带贬义。", context: "北方人初到南方，常因湿热气候而水土不服，需要一段时间的适应过程。" },
  { idiom: "物极必反", meaning: "指事物发展到极点就会向相反方向转化。强调事物在一定条件下会走向自身的反面，多用于形容盛极而衰、乐极生悲等现象。中性。", context: "一味追求速度与规模，往往会带来质量隐患，物极必反，企业发展需要把握好节奏。" },
  { idiom: "弄巧成拙", meaning: "指本想耍弄聪明、做得巧妙，结果反而坏了事，显得笨拙。强调因自以为聪明而做出不恰当的处理，结果适得其反，多用于批评好心办坏事或聪明反被聪明误。贬义。", context: "他想在领导面前表现自己的能力，擅自修改了方案，结果弄巧成拙，导致项目出了大问题。" },
  { idiom: "不可或缺", meaning: "指不可缺少、非常重要。强调某事物是整体中必不可少的组成部分，多用于形容要素、条件、能力等在整体中的关键地位。褒义。", context: "诚信是市场经济健康运行的基石，不可或缺。" },
  { idiom: "首当其冲", meaning: "指最先受到攻击或遭遇灾难。强调处于最前面、最先承受冲击或压力，多用于形容在冲突或灾难中首先受到波及。中性（常被误用为“首要”“首先”）。", context: "沿海城市在台风来袭时往往首当其冲，需要提前做好防台准备。" },
  { idiom: "必不可少", meaning: "指绝对需要、不可缺少。强调某事物存在的必要性，多用于形容条件、因素、能力等在特定情境下的不可或缺。褒义。", context: "团队协作是完成这项复杂任务的必不可少的条件。" },
  { idiom: "横空出世", meaning: "指突然出现或诞生，形容事物突然问世、令人瞩目。强调凭空出现、势头强劲，多用于形容新事物、新作品、新人物等的惊艳亮相。褒义。", context: "这部科幻大片横空出世，凭借震撼的视觉效果迅速风靡全球。" },
  { idiom: "初露锋芒", meaning: "指刚显露才华或力量，比喻刚开始展现才能。强调初次展示才华、崭露头角，多用于形容新人或新事物刚刚展现出潜力。褒义。", context: "这位年轻画家在本次展览中初露锋芒，其作品引起了艺术界的广泛关注。" },
  { idiom: "大放异彩", meaning: "指发出耀眼的光彩，比喻取得突出成就、展现非凡魅力。强调在某领域或场合中大显身手、大获成功，多用于形容在比赛中、舞台上或某一时期表现出色。褒义。", context: "中国代表团在奥运会上大放异彩，勇夺多枚金牌，为祖国赢得了荣誉。" },
  { idiom: "崭露头角", meaning: "指头上的角已明显地突出来了，比喻突出地显露出才能和本领。强调刚开始展现才能、显露才华，多用于形容新人在某个领域开始展现实力。褒义。", context: "这位青年歌手在音乐比赛中崭露头角，凭借出色的唱功赢得了评委的一致好评。" },
  { idiom: "声名鹊起", meaning: "指名声像喜鹊一样突然飞起，形容名声迅速提高。强调知名度在短时间内快速提升、一炮而红，多用于形容人或事物突然走红。褒义。", context: "这家小餐馆因一道招牌菜而声名鹊起，吸引了众多美食爱好者慕名而来。" },
  { idiom: "后来居上", meaning: "指后来的人或事物超过了先前的，超过了前者。强调后发优势、超越前者，多用于形容在竞争或发展中后来者超越先者。褒义。", context: "该团队虽然起步较晚，但凭借技术创新后来居上，在行业内占据了领先地位。" },
  { idiom: "脱颖而出", meaning: "指锥尖透过布袋显露出来，比喻人的才能全部显露出来。强调从众多人中突显出来、崭露头角，多用于形容人才被发现或展现才能。褒义。", context: "在此次大赛中，多位青年演员脱颖而出，展现了扎实的表演功底。" },
  { idiom: "文过饰非", meaning: "指用漂亮的言词掩饰自己的过失和错误。强调刻意美化、掩盖错误，多用于批评不敢正视问题、推卸责任的行为。贬义。", context: "面对问题，与其文过饰非，不如坦诚面对、及时改正，这样才能赢得信任。" },
  { idiom: "掩耳盗铃", meaning: "比喻自己欺骗自己，明明掩盖不了的事偏要设法掩盖。强调自欺欺人、试图掩盖真相，多用于批评明知不可为而为之的愚蠢做法。贬义。", context: "对安全隐患视而不见，无异于掩耳盗铃，最终只会酿成大祸。" },
  { idiom: "避重就轻", meaning: "指回避重的责任，只拣轻的来承担。也指回避要害问题，只说次要问题。强调回避主要矛盾或重大责任，多用于批评不敢担当、推卸责任的态度。贬义。", context: "在汇报工作时，不能避重就轻，只谈成绩不谈问题，而要实事求是。" },
  { idiom: "与时俱进", meaning: "指随着时代的发展而不断发展、前进。强调紧跟时代步伐、不断更新观念和做法，多用于形容思想、理念、政策等顺应时代变化。褒义。", context: "马克思主义具有与时俱进的理论品质，在实践中不断丰富和发展。" },
  { idiom: "脚踏实地", meaning: "指脚踏在坚实的土地上，比喻做事踏实、认真、不浮夸。强调务实肯干、一步一个脚印，多用于形容工作作风或学习态度。褒义。", context: "青年人要有理想抱负，更要脚踏实地，从点滴做起，在实践中增长才干。" },
  { idiom: "学以致用", meaning: "指把学到的知识运用到实际中去。强调学用结合、知行合一，多用于形容学习的目的在于指导实践。褒义。", context: "读书学习要注重学以致用，把理论知识转化为解决实际问题的能力。" },
  { idiom: "实事求是", meaning: "指从实际情况出发，正确地对待和处理问题，不夸大不缩小。强调尊重客观事实、一切从实际出发，多用于形容工作态度、思想路线。褒义。", context: "调查研究要坚持实事求是，深入一线了解真实情况，为决策提供可靠依据。" },
  { idiom: "责无旁贷", meaning: "指自己应尽的责任，不能推卸给别人。强调责任感强、义不容辞，多用于形容分内之事必须承担。褒义。", context: "保护生态环境，每个公民都责无旁贷。" },
  { idiom: "义不容辞", meaning: "指道义上不允许推辞，理应承担。强调从道义上应尽的责任，多用于形容在道义面前勇敢担当、不推诿。褒义。", context: "救死扶伤是医生的天职，义不容辞。" },
  { idiom: "当仁不让", meaning: "原指以仁为任，无所谦让，后指遇到应该做的事，积极主动去做，不退让。强调积极主动担当责任，多用于形容在分内事上不推让、勇于争先。褒义。", context: "在危险面前，党员干部当仁不让，冲在最前面。" },
  { idiom: "自不待言", meaning: "指当然不用说，不言而喻。强调某事物或道理显而易见，不需要多说。中性或褒义。", context: "自贸区成立以来，营商环境持续优化，其积极影响自不待言。" },
  { idiom: "清道夫", meaning: "原指清扫街道的工人，现比喻清除不良现象、维护秩序的人或事物。强调清除障碍、净化环境，多用于形容在某一领域中起到净化、整治作用的力量。中性或褒义。", context: "网络监督是净化网络环境的清道夫，有助于及时清除有害信息。" },
  { idiom: "责任田", meaning: "原指农村集体土地承包到户的耕地，现比喻个人或部门分工负责的职责范围或工作任务。强调明确责任、各司其职，多用于形容岗位职责的划分。中性或褒义。", context: "每位干部都要种好自己的责任田，确保各项工作任务落实到位。" },
  { idiom: "防火墙", meaning: "原指建筑物中起防火隔离作用的墙，现比喻用于抵御外部入侵或防止问题扩散的屏障。强调安全防护、隔离风险，多用于形容网络安全、制度防范等领域。褒义或中性。", context: "网络防火墙是维护国家信息安全的重要屏障。" },
  { idiom: "过滤网", meaning: "原指用于过滤液体或气体的网状装置，现比喻筛选、过滤不良或无用信息的事物。强调筛选功能、去粗取精，多用于形容信息筛选、人员选拔等。中性或褒义。", context: "严格的审核机制就像一道过滤网，确保发布的内容真实可靠。" },
  { idiom: "徒劳无功", meaning: "指白白付出劳动而没有成效。强调付出努力却没有任何成果，多用于形容努力白费、毫无回报。贬义。", context: "在缺乏调研的情况下盲目推进项目，结果只能是徒劳无功，浪费大量人力物力。" },
  { idiom: "一纸空文", meaning: "指一张空白的文书，比喻没有实际效力或不起作用的书面规定。强调文件、政策、合同等只有形式而无实质效力，多用于批评制度虚设、执行不力。贬义。", context: "如果监管不到位，再完善的法律也不过是一纸空文，无法真正约束违法行为。" },
  { idiom: "虚有其表", meaning: "指外表好看、实际不行，空有好看的外表而内在空虚。强调外表与实质不符、有名无实，多用于形容人或事物徒有虚名。贬义。", context: "这家餐厅装修豪华，菜品却虚有其表，味道平平，令人失望。" },
  { idiom: "混淆是非", meaning: "指把对的说成错的、错的说成对的，故意颠倒黑白。强调故意混淆正确与错误的界限，多用于批评有意歪曲事实、混淆视听的行为。贬义。", context: "舆论监督要基于事实，不能混淆是非，误导公众判断。" },
  { idiom: "明知故犯", meaning: "指明明知道不对，却故意违犯。强调知错犯错、明知不可为而为之，多用于批评故意违规或明知故错的行为。贬义。", context: "一些企业明知故犯，在环保数据上弄虚作假，必须予以严惩。" },
  { idiom: "有恃无恐", meaning: "指因有所倚仗而毫无顾虑或无所畏惧。强调仗着某种条件或靠山而大胆妄为、不怕后果，多用于批评仗势胡作非为的行为。贬义。", context: "个别执法人员有恃无恐，滥用职权，严重损害了政府形象。" },
  { idiom: "本末倒置", meaning: "指把根本的、主要的事和枝节的、次要的事颠倒了位置。强调主次颠倒、轻重不分，多用于批评做事分不清主次、抓不住重点。贬义。", context: "发展经济不能本末倒置，以牺牲环境为代价换取短期增长，是舍本逐末的行为。" },
  { idiom: "对症下药", meaning: "指针对病症开方用药，比喻针对问题所在，采取有效的措施。强调问题导向、精准施策，多用于形容解决问题时有针对性的方法。褒义。", context: "治‘躺平式干部’需对症下药、多管齐下，既加强教育引导，也完善考核机制。" },
  { idiom: "审时度势", meaning: "指观察分析时势，估量情况的变化，以制定合适的方针或策略。强调冷静、理智地观察外部环境与形势发展，做出正确判断。多用于战略决策、宏观规划等语境。褒义。", context: "领导者必须审时度势，根据国内外形势的变化，及时调整发展战略。" },
  { idiom: "当机立断", meaning: "指抓住时机，立刻做出决断。强调在关键时刻果断决策、不犹豫，多用于形容在紧急或重要时刻的果敢魄力。褒义。", context: "面对突发险情，指挥员当机立断，迅速下达了疏散命令，避免了人员伤亡。" },
  { idiom: "如出一辙", meaning: "比喻两件事情非常相似，像出自同一个车辙一样。强调相似度高、行为或现象几乎一样，多用于批评类似错误或负面行为的重复出现。贬义或中性。", context: "这两起诈骗案件的作案手法如出一辙，很可能是同一团伙所为。" },
  { idiom: "殊途同归", meaning: "指通过不同的途径，到达同一个目的地。比喻采取的方法不同，但达到的结果相同。强调途径不同而结果一致，多用于形容方法多样但目的一致。褒义或中性。", context: "无论是科技创新还是文化传承，虽然路径不同，但殊途同归，最终都是为了推动社会进步。" },
  { idiom: "双管齐下", meaning: "指两管笔同时并写，比喻两方面同时进行。强调从两个方面同时入手、同步推进，多用于形容解决问题的综合策略。褒义。", context: "治理环境污染要双管齐下，既从严执法，又推动产业转型升级。" },
  { idiom: "浑浑噩噩", meaning: "形容糊里糊涂、无知无识的样子，也形容生活平庸、没有追求。强调精神空虚、不求上进、过得糊里糊涂，多用于批评没有目标、缺乏进取心的生活状态。贬义。", context: "年轻人正值奋斗年华，不能浑浑噩噩、虚度光阴，而应树立远大理想，努力拼搏。" },
  { idiom: "唯唯诺诺", meaning: "形容一味顺从、不敢发表意见、低声下气的样子。强调缺乏主见、一味附和、不敢表达真实想法，多用于批评没有胆识和独立人格的态度。贬义。", context: "作为干部，要有担当精神，不能唯唯诺诺、事事附和，而应敢于直言、勇于负责。" },
  { idiom: "无所事事", meaning: "指什么事都不干、闲荡无事。强调空闲懒惰、没有做任何有意义的事情，多用于批评游手好闲、不务正业的状态。贬义。", context: "与其整天无所事事，不如利用时间学习一门新技能，为未来积蓄力量。" },
  { idiom: "无所作为", meaning: "指没有做出任何成绩或贡献，形容安于现状、不求进取。强调缺乏建树、没有积极作为，多用于批评工作懈怠、不作为的态度。贬义。", context: "在改革攻坚的关键时期，领导干部绝不能无所作为，必须主动担当、积极作为。" },
  { idiom: "不耻下问", meaning: "指不以向地位比自己低、知识比自己少的人请教为可耻。强调谦虚好学、乐于向他人学习，多用于形容虚心求教的态度。褒义。", context: "做学问要不耻下问，善于从不同领域、不同层次的人身上汲取智慧。" },
  { idiom: "兼收并蓄", meaning: "指把各种不同内容的东西都吸收、保存起来。强调广泛接纳、包容多样，多用于形容文化、学术、艺术等的包容性发展。褒义。", context: "中华文明之所以绵延数千年，正是因为能够兼收并蓄，不断吸收外来文化的精华。" },
  { idiom: "虚怀若谷", meaning: "指胸怀像山谷那样深广，形容非常谦虚、能容纳各种意见。强调心胸开阔、谦虚大度，多用于形容人的品德修养。褒义。", context: "真正的学者总是虚怀若谷，越是学识渊博，越懂得尊重他人的见解。" },
  { idiom: "各抒己见", meaning: "指各自充分发表自己的意见和见解。强调每个人都坦诚表达自己的观点，多用于形容讨论、研讨时畅所欲言的氛围。褒义或中性。", context: "在民主生活会上，大家各抒己见，围绕工作方案提出了许多建设性意见。" },
  { idiom: "百家争鸣", meaning: "指各种学术流派、观点自由争论、相互竞争。强调学术或思想的自由交流与碰撞，多用于形容文化、学术领域百花齐放的局面。褒义。", context: "春秋战国时期，诸子百家百家争鸣，共同奠定了中华文化的思想根基。" },
  { idiom: "取长补短", meaning: "指吸取别人的长处来弥补自己的短处。强调相互借鉴、优势互补，多用于形容学习、合作中取人之长补己之短。褒义。", context: "不同地区之间应加强交流合作，取长补短，共同推动区域协调发展。" },
  { idiom: "从善如流", meaning: "指听从好的、正确的意见，像流水一样自然、顺畅。强调从谏如流、善于接受他人好的建议。褒义。", context: "领导干部要从善如流，虚心听取群众的意见建议，不断改进工作作风。" },
  { idiom: "以偏概全", meaning: "指用片面的观点看待整体，以局部代替全体。强调因所见不全而得出错误结论，多用于批评只看局部不看整体的思维偏差。贬义。", context: "评价一个人不能以偏概全，因一次失误就否定他的全部努力。" },
  { idiom: "一孔之见", meaning: "指从一个小孔里看到的景象，比喻狭隘片面的见解。强调见解狭窄、视野受限，多用于自谦或批评他人眼界不宽。贬义或自谦。", context: "以上只是我的一孔之见，希望能抛砖引玉，听到更多专家的真知灼见。" },
  { idiom: "闭门造车", meaning: "指关起门来造车，比喻脱离实际、只凭主观办事。强调不联系实际情况、不调查研究的做法，多用于批评脱离实际、主观臆断的行为。贬义。", context: "政策制定不能闭门造车，必须深入基层调研，倾听群众心声。" },
  { idiom: "一视同仁", meaning: "指对人同样看待，不分亲疏厚薄。强调公平对待、不偏袒，多用于形容在待人接物上态度公正、没有偏私。褒义。", context: "教育应当一视同仁，让每个孩子都能享受到公平而有质量的教育资源。" },
  { idiom: "等量齐观", meaning: "指把不同的事物一律同等看待。强调把高低轻重不同的事物放在同等地位对待，多用于批评不加区分、一律对待的做法。中性或略带贬义。", context: "两种方法各有优劣，不能等量齐观，应根据实际情况选择最合适的方案。" },
  { idiom: "面面俱到", meaning: "指各方面都照顾到，没有遗漏。强调考虑周全、没有疏漏，多用于形容做事考虑周详、没有遗漏。中性或褒义。", context: "这份规划面面俱到，涵盖了经济、社会、生态等各个领域，具有很好的指导意义。" },
  { idiom: "不偏不倚", meaning: "指不偏袒任何一方，保持中立公正。强调立场客观、处事公平，多用于形容裁判、评价、态度等方面的公正。褒义。", context: "作为裁判，必须不偏不倚，以事实为依据，以规则为准绳。" },
  { idiom: "因地制宜", meaning: "指根据各地的具体情况，制定适宜的办法。强调因地点不同而采取不同的措施，多用于形容政策制定、工作方法上的针对性。褒义。", context: "各地要因地制宜，充分利用本地资源优势，推动乡村振兴取得实效。" },
  { idiom: "坚定不移", meaning: "指态度、主张等非常坚定，毫不动摇。强调立场坚定、不因外界因素而改变，多用于形容信念、决心、方向等的持久稳定。褒义。", context: "无论国际风云如何变幻，我们都要坚定不移地走和平发展道路。" },
  { idiom: "声势浩大", meaning: "指声威和气势非常盛大。强调规模宏大、影响广泛，多用于形容运动、活动、行动等的气势磅礴。褒义或中性。", context: "群众性的健身运动声势浩大，吸引了数十万市民参与。" },
  { idiom: "惊天动地", meaning: "形容声音极大或事业、事件等极其伟大、震动人心。强调影响巨大、震撼人心，多用于形容大事件、大变革或重大成就。褒义或中性。", context: "改革开放是惊天动地的伟大变革，深刻改变了中国的面貌。" },
  { idiom: "显山露水", meaning: "比喻显露出来、引人注目，多指才能、成绩等显现出来。强调从隐蔽或平凡中显现出来，多用于形容人或事物的成绩被外界看到。中性或褒义。", context: "他在基层默默耕耘了多年，如今终于有机会显山露水，展现自己的才华。" },
  { idiom: "轰轰烈烈", meaning: "形容事业、运动等气魄宏大、声势壮观，也形容激情高涨、充满活力的状态。强调气魄宏大、激情昂扬，多用于形容改革、运动、事业等的壮阔场面。褒义。", context: "一代代青年曾在轰轰烈烈的社会主义建设热潮中挥洒汗水、奉献青春。" },
  { idiom: "家喻户晓", meaning: "家家户户都知道，形容尽人皆知。强调传播范围广、人人皆知，多用于形容知名度极高的人、事、物。中性或褒义。", context: "让一枚小小的青橄榄从‘藏在深闺无人知’到家喻户晓、产销两旺，品牌效应辐射全国。" },
  { idiom: "有目共睹", meaning: "指人人都能看到，形容事实极其明显。强调事物清晰可见、无可否认，多用于形容成绩、变化、事实等的明显性。褒义或中性。", context: "中国脱贫攻坚取得的成就有目共睹，数亿贫困人口成功脱贫。" },
  { idiom: "一目了然", meaning: "形容一眼就能看清、看明白，事物非常清晰。强调清晰易懂、无需复杂分析，多用于形容图表、说明、布局等直观明了。中性或褒义。", context: "这张示意图设计得十分简洁，城市交通脉络一目了然。" },
  { idiom: "引人注目", meaning: "指引起人们的注意，形容人或事物特别突出、容易被人看到。强调具有吸引力或特殊性，容易成为关注的焦点。中性或褒义。", context: "展厅中央的巨型雕塑引人注目，成为了整个展览的焦点。" },
  { idiom: "精打细算", meaning: "指仔细地计算、周密地筹划，形容做事计划周密、不浪费。强调算计精细、合理安排，多用于形容资金、时间、资源等的精心规划。褒义。", context: "过日子要懂得精打细算，把每一分钱都花在刀刃上。" },
  { idiom: "物尽其用", meaning: "指充分利用各种物品，不浪费，使其效能得到最大发挥。强调发挥每一件物品的最大价值，多用于形容资源利用的充分性。褒义。", context: "旧物改造不仅能让物尽其用，减少浪费，还能为生活增添创意乐趣。" },
  { idiom: "量入为出", meaning: "指根据收入的多少来安排支出的限度。强调按照收入水平合理规划支出，多用于形容理财观念或经济管理中的稳健原则。褒义。", context: "家庭理财要坚持量入为出的原则，避免过度消费、超前消费。" },
  { idiom: "开源节流", meaning: "指开辟新的财源，节省不必要的开支。强调增加收入的同时减少浪费，多用于形容经济管理、企业运营中的双管齐下策略。褒义。", context: "面对成本压力，企业既要开源节流，控制运营成本，也要积极拓展新的利润增长点。" },
  { idiom: "薪火相传", meaning: "比喻学问、技艺、精神等代代相传，像柴火传火一样前柴烧尽后柴续燃。强调代际传承、生生不息，多用于形容文化、传统、精神的延续。褒义。", context: "中华优秀传统文化薪火相传，在一代代人手中发扬光大。" },
  { idiom: "枝繁叶茂", meaning: "形容树木枝叶繁密茂盛，比喻家族人丁兴旺、事业繁荣或文化昌盛。强调兴旺发达、蓬勃发展，多用于形容事业、家族、文化等的繁荣状态。褒义。", context: "如今，这所百年名校已是枝繁叶茂，培养出了数万名各行各业的人才。" },
  { idiom: "落地生根", meaning: "指在某地扎根、安家落户，比喻在异乡稳定下来、融入当地。强调适应新环境并站稳脚跟，多用于形容移民、企业、文化等在异地扎根发展。褒义或中性。", context: "这批返乡创业的青年不仅在故土落地生根，还带动了当地产业蓬勃发展。" },
  { idiom: "生生不息", meaning: "指不断地生长、繁衍、发展，永不停息。强调生命力持续涌动、永续发展，多用于形容文化、生命、精神等的永恒延续。褒义。", context: "博大精深的中华文化，为中华民族生生不息、发展壮大提供了强大精神支撑。" },
  { idiom: "高谈阔论", meaning: "指漫无边际地大发议论，多含贬义。强调谈论的内容空泛不切实际，或态度傲慢、夸夸其谈，多用于批评空谈而不解决问题的言论。贬义。", context: "实干兴邦，空谈误国，与其高谈阔论，不如脚踏实地解决实际问题。" },
  { idiom: "空穴来风", meaning: "原指有了洞穴才有风进来，比喻消息和传说不是完全没有原因的。强调事出有因、并非毫无根据，多用于形容传言有一定来源（不可误用为“毫无根据”）。中性。", context: "关于该公司即将重组的传闻并非空穴来风，业内人士透露确有相关计划在酝酿中。" },
  { idiom: "海市蜃楼", meaning: "原指海边或沙漠中因光线折射而出现的幻景，比喻虚无缥缈、不切实际的幻想或事物。强调虚幻不实、无法实现，多用于形容脱离现实的空想或假象。贬义。", context: "如果不从实际出发，再美好的规划也不过是海市蜃楼，难以真正落地。" },
  { idiom: "披荆斩棘", meaning: "指劈开荆棘，比喻在创业或前进道路上清除障碍、克服困难。强调排除万难、奋勇前进的精神，多用于形容创业或改革历程。褒义。", context: "在科技创新的道路上，科研人员披荆斩棘，攻克了一个又一个难关。" },
  { idiom: "久久为功", meaning: "指持之以恒、坚持不懈地努力，最终取得成效。强调长期坚持、不急于求成，多用于形容重大工程、长远事业的推进。褒义。", context: "生态修复是一项长期任务，必须久久为功，一代接着一代干。" },
  { idiom: "兢兢业业", meaning: "指小心谨慎、认真负责的样子。强调做事谨慎、勤恳负责、不敢有丝毫懈怠，多用于形容工作态度。褒义。", context: "他在岗位上兢兢业业工作了三十年，深受同事和领导的尊敬。" },
  { idiom: "相去甚远", meaning: "指互相之间距离很远，差距很大。强调两者之间存在明显差距或差别，多用于比较。中性。", context: "理想与现实往往相去甚远，需要不断努力才能缩小差距。" },
  { idiom: "水火不容", meaning: "比喻两者根本对立、互不相容，像水和火一样不能共存。强调极端对立、无法调和，矛盾激烈。贬义。", context: "诚信经营与欺诈行为水火不容，任何企业都不能触碰这条红线。" },
  { idiom: "盘根错节", meaning: "指树根盘绕、枝节交错，比喻事情或关系纷繁复杂、难以理顺。强调事物内部关系交错纠缠、头绪繁多，多用于形容问题、矛盾、关系等的复杂程度。中性或略带贬义。", context: "基层治理面临的问题盘根错节，需要多方协调、综合施策才能有效解决。" },
  { idiom: "错综复杂", meaning: "指头绪繁多、相互交织、复杂难辨。强调头绪众多、关系交叉，多用于形容局面、关系、问题等的复杂状况。中性。", context: "国际形势错综复杂，各国利益相互交织，合作共赢才是正确选择。" },
  { idiom: "包罗万象", meaning: "指内容非常丰富，包含了宇宙间的一切景象或事物。强调涵盖范围极广、无所不有，多用于形容知识体系、展览、著作、商品种类等。褒义。", context: "这部百科全书内容包罗万象，从天文地理到人文历史，应有尽有。" },
  { idiom: "任重道远", meaning: "指担子很重，路程又长，比喻责任重大，需要长期艰苦努力。强调使命重大、路途漫长，多用于形容重大事业、长远目标。褒义。", context: "乡村振兴是一项长期任务，任重道远，需要我们坚持不懈地推进。" },
  { idiom: "高屋建瓴", meaning: "指在屋顶上倒水，水从高处顺势流下。比喻居高临下、势不可挡，也形容对事物有全局性的、高瞻远瞩的把握。强调站位高远、视野开阔，多用于形容战略眼光、宏观把握能力。褒义。", context: "这篇报告高屋建瓴，从全局高度分析了行业发展趋势，具有很强的指导意义。" },
  { idiom: "追根溯源", meaning: "指追溯事物的根源、探寻其来龙去脉。强调追溯源头、探寻本质，多用于形容查找问题根源、研究历史渊源。褒义或中性。", context: "要解决这一环境问题，必须追根溯源，找到污染的真正源头。" },
  { idiom: "防患未然", meaning: "指在祸患发生之前就加以预防。强调提前采取措施、防患于未然，多用于形容有远见的防范意识。褒义。", context: "安全生产要防患未然，定期排查隐患，不能等到事故发生后再补救。" },
  { idiom: "亡羊补牢", meaning: "指丢了羊再去修补羊圈，比喻出了问题后及时补救，还不算晚。强调事后采取补救措施、防止损失扩大，多用于形容知错就改、及时止损的意识。中性或褒义。", context: "虽然这次项目因为疏忽造成了损失，但现在亡羊补牢犹未为晚，及时整改还能避免更大的问题。" },
  { idiom: "惩前毖后", meaning: "指惩处以往的过错，以警戒将来不再重犯。强调通过处理过去的错误来警示未来、防止再犯，多用于形容以惩罚为手段达到教育目的。褒义。", context: "对违纪行为的严肃处理，目的在于惩前毖后，教育广大干部引以为戒。" },
  { idiom: "补偏救弊", meaning: "指补救偏差、纠正弊端。强调针对存在的偏差和缺陷进行修正和补救，多用于形容改革、整治中的纠正措施。褒义。", context: "这项改革的目的在于补偏救弊，完善现有制度中的不足之处。" },
  { idiom: "深谋远虑", meaning: "指周密地计划，往长远里考虑。强调谋划深远、思虑周全，多用于形容具有长远眼光和周密策略的决策者。褒义。", context: "这项战略决策体现了领导者的深谋远虑，为未来发展奠定了坚实基础。" },
  { idiom: "司空见惯", meaning: "指看惯了就不觉得奇怪。强调因常见而习以为常、不再感到新奇，多用于形容现象或事物普遍存在、不足为奇。中性。", context: "城市里的车水马龙早已司空见惯，但偶尔的宁静反而让人更加珍惜。" },
  { idiom: "烂熟于心", meaning: "指对事物非常熟悉，像心里都烂透了一样，形容记得极熟。强调对知识、内容等掌握得极为透彻、牢记在心，多用于形容背书、记忆等方面的纯熟程度。褒义。", context: "他早已将操作规程烂熟于心，每一个步骤都做得精准到位，从不出错。" },
  { idiom: "手到擒来", meaning: "指手一伸就能擒获，比喻做事极有把握、非常容易。强调因熟练或准备充分而轻松完成，多用于形容做事毫不费力、十拿九稳。褒义。", context: "这些简单的维修对他来说手到擒来，三两下就能搞定。" },
  { idiom: "习以为常", meaning: "指某种事情经常去做或某种现象经常看到，也就觉得很平常了。强调因长期重复而视为常态、不以为奇，多用于形容习惯成自然的状态。中性。", context: "山区教师每天走十几里山路去上课，这样的生活他们早已习以为常。" },
  { idiom: "设身处地", meaning: "指设想自己处在别人的地位或境遇中，替别人着想。强调从他人的角度出发思考问题，多用于形容理解他人处境、体谅他人的态度。褒义。", context: "做群众工作要设身处地为群众着想，真正理解他们的困难和诉求。" },
  { idiom: "推己及人", meaning: "指用自己的心意去推想别人的心意，设身处地替别人着想。强调以自己的感受去理解他人，多用于形容将心比心、体谅他人的道德品质。褒义。", context: "做人要学会推己及人，多站在别人的角度考虑问题，社会就会更加和谐。" },
  { idiom: "将心比心", meaning: "指拿自己的心去比照别人的心，比喻设身处地替别人着想。强调换位思考、理解他人感受，多用于形容沟通和理解中的共情能力。褒义。", context: "处理邻里纠纷时，要将心比心，互相理解，才能化解矛盾。" },
  { idiom: "感同身受", meaning: "原指感激的心情如同亲身受到恩惠一样，现多指虽未亲身经历，但感受就像亲身经历过一样。强调对他人遭遇的深切理解和共鸣，多用于形容强烈的共情体验。褒义。", context: "虽然没有经历过地震，但看到灾区群众的遭遇，我们也能感同身受，纷纷伸出援手。" },
  { idiom: "束手无策", meaning: "指遇到问题就像手被捆住一样，毫无办法。强调无可奈何、完全没办法应对，常与“面对”“陷入”等搭配。贬义或中性。", context: "面对突如其来的洪水，如果没有充分的应急预案，就会束手无策。" },
  { idiom: "易如反掌", meaning: "指像翻一下手掌那样容易，形容事情极其简单易行。强调事情简单到不费吹灰之力，多用于形容难度极低的事。褒义。", context: "对于熟练的程序员来说，解决这个Bug易如反掌，但对于新手来说却需要琢磨很久。" },
  { idiom: "游刃有余", meaning: "指刀刃在骨节间运转时还有余地，比喻做事从容不迫、轻松自如，能力绰绰有余。强调应对自如、毫无压力，多用于形容技术纯熟、做事轻松。褒义。", context: "他处理这类复杂问题时总是游刃有余，沉稳从容，令人钦佩。" },
  { idiom: "长驱直入", meaning: "指军队长距离地、不受阻碍地迅速进军，比喻行动迅速、畅通无阻。强调行军或行动毫无阻碍、一路直进，多用于形容军事进攻、市场开拓等。褒义或中性。", context: "起义军势如破竹，长驱直入，很快攻占了敌军的重要据点。" },
  { idiom: "走马观花", meaning: "比喻粗略地观察一下，不深入细致。强调速度快、不深入，多用于形容观察、游览等。中性或贬义。", context: "调查研究不能走马观花，必须沉下身子、深入基层。" },
  { idiom: "挂一漏万", meaning: "指列举到的只是很少的一部分，遗漏的很多。强调列举不全、遗漏甚多，多用于自谦或形容列举的不完备。中性或自谦。", context: "以上列举的只是几个典型案例，挂一漏万，还有很多优秀事迹无法一一提及。" },
  { idiom: "众望所归", meaning: "指众人的信任和期望归向某人，形容某人得到大家的信赖，很自然地成为领导者或受推崇者。强调深孚众望、当之无愧，多用于形容某人因德才兼备而自然成为大家公认的领袖或代表。褒义。", context: "这位德高望重的老科学家当选为学会主席，可谓众望所归。" },
  { idiom: "当之无愧", meaning: "指完全当得起某种称号或荣誉，没有可惭愧的地方。强调名副其实、值得所获得的荣誉，多用于称赞某人凭实力配得上所获的称号、奖项。褒义。", context: "他几十年如一日扎根基层、服务群众，被评为人民好公仆当之无愧。" },
  { idiom: "独占鳌头", meaning: "指占据首位，获得第一名。强调位居第一、无人超越，多用于形容在比赛、考试中取得冠军。褒义。", context: "这支代表队凭借出色发挥，在决赛中独占鳌头，捧起了冠军奖杯。" },
  { idiom: "不折不扣", meaning: "指不打折扣，完全、十足。强调没有任何缩减或折扣，完完全全、地地道道，多用于形容数量、品质、标准等的完全达标，有时也用于强调某种身份或特征的真实性。中性或褒义。", context: "这支队伍不折不扣地执行了上级下达的各项指令，圆满完成了救援任务。" },
  { idiom: "陈陈相因", meaning: "原指仓库里的粮食逐年堆积，陈粮压陈粮，现比喻沿袭老一套，没有创新。强调因循守旧、缺乏革新，多用于批评在制度、方法、内容等方面的呆板重复。贬义。", context: "学术研究要勇于突破，不能陈陈相因，重复前人的老路而不思创新。" },
  { idiom: "抱残守缺", meaning: "指抱着残缺陈旧的东西不放，形容思想保守、不愿接受新事物。强调固守残缺、拒绝革新，多用于批评不肯变革、留恋旧物的态度。贬义。", context: "在技术飞速发展的今天，企业如果依然抱残守缺，很快就会被市场淘汰。" },
  { idiom: "食古不化", meaning: "指学了古代的知识，却不能灵活运用，像吃东西不消化一样。强调生搬硬套古代知识、脱离实际，多用于批评机械学习、不知变通的态度。贬义。", context: "研究传统文化不能食古不化，要取其精华、去其糟粕，与现代生活相结合。" },
  { idiom: "墨守成规", meaning: "指固执地守着老规矩，不思改变。强调死守旧规矩、不肯变通，多用于形容守旧、不创新的作风。贬义。", context: "面对新的市场环境，我们不能墨守成规，必须大胆创新，才能赢得发展机遇。" },
  { idiom: "纸上谈兵", meaning: "比喻只在空谈理论，不能解决实际问题；也比喻只凭书本知识空发议论，不能成功。强调有理论无实践、脱离实际操作，典出赵括兵败典故。贬义。", context: "方案再完美，不落到实处也只是纸上谈兵，毫无意义。" },
  { idiom: "天马行空", meaning: "指天马奔驰于天空，比喻思想奔放、不受拘束，也形容诗文、书法等气势豪放、流畅自然。强调想象力的自由驰骋、不受局限，多用于形容才思敏捷、文笔奔放，也可能批评不切实际（视语境而定）。褒义或中性（批评语境下可含贬义）。", context: "这位诗人的想象力天马行空，作品充满了奇幻色彩，令人叹服。" },
  { idiom: "向壁虚造", meaning: "指对着墙壁凭空捏造，比喻凭空捏造、虚构事实。强调毫无根据的捏造、编造，多用于批评虚构事实、无中生有的行为。贬义。", context: "这篇报道的内容完全是向壁虚造，毫无事实依据，严重违背了新闻职业道德。" },
  { idiom: "恣意妄为", meaning: "指毫无顾忌地胡作非为、肆意妄行。强调放纵任性、不守规矩，多用于批评滥用权力或无视法律的行为。贬义。", context: "法治社会绝不允许任何人恣意妄为，任何违法行为都将受到法律的严惩。" },
  { idiom: "正本清源", meaning: "指从根源上加以整顿清理，从根本上彻底解决问题。强调从源头入手、彻底整治，多用于形容对问题根源的系统性治理。褒义。", context: "要正本清源，坚决整治行业乱象，从制度层面杜绝违规行为的发生。" },
  { idiom: "返璞归真", meaning: "指去掉外在的装饰，恢复原来的质朴状态。强调回归本真、摒弃虚饰，多用于形容生活态度、艺术风格等的质朴自然。褒义。", context: "在喧嚣的都市生活中，越来越多的人开始追求返璞归真的生活方式，向往自然的宁静。" },
  { idiom: "拨乱反正", meaning: "指治理混乱的局面，使回到正常正确的轨道上来。强调纠正错误、扭转混乱，多用于形容政治、思想、路线等方面的重大纠正。褒义。", context: "改革开放后，党领导人民拨乱反正，使国家各项事业重新走上了健康发展的轨道。" },
  { idiom: "固本强基", meaning: "指巩固根本、强化基础。强调打牢根基、强化基础建设，多用于形容在基层建设、基础工作等方面的夯实举措。褒义。", context: "要不断加强基层党组织建设，固本强基，为各项事业发展提供坚强的组织保障。" },
  { idiom: "不分彼此", meaning: "指不分你我，关系极为密切。强调彼此之间没有界限、融为一体，多用于形容感情深厚、关系融洽，不分亲疏。褒义。", context: "两支队伍在合作中不分彼此，互相支持、资源共享，共同完成了这项艰巨的任务。" },
  { idiom: "厚此薄彼", meaning: "指重视或优待一方，轻视或冷落另一方。强调偏心、不公平对待，多用于批评待人接物上的偏袒行为。贬义。", context: "分配资源时要一碗水端平，不能厚此薄彼，让部分单位感到不公。" },
  { idiom: "顾此失彼", meaning: "指顾了这个，丢了那个。形容忙乱或慌张的情景，无法兼顾所有方面。强调因头绪太多或准备不足而导致应付不过来，多用于形容工作安排、资源分配等方面的失衡。贬义或中性。", context: "基层工作千头万绪，稍有不慎就会顾此失彼，需要合理安排、统筹兼顾。" },
  { idiom: "此消彼长", meaning: "指这个下降，那个上升。强调双方处于动态的竞争或对立关系中，一方减弱则另一方增强，多用于形容力量对比、市场占有、利弊关系等。中性。", context: "在市场竞争中，各品牌之间此消彼长，没有永远的赢家。" },
  { idiom: "一成不变", meaning: "指一经形成就不再改变，形容墨守成规、毫无变化。强调固定不变、缺乏灵活性，多用于批评思想或做法僵化守旧。贬义或中性。", context: "时代在发展，我们的工作方法也不能一成不变，必须与时俱进、不断创新。" },
  { idiom: "与众不同", meaning: "指跟大家不一样，具有独特之处。强调与普通事物不同、独具特色，多用于形容人的气质、风格或作品、设计等的独特性。褒义或中性。", context: "这位设计师的作品风格与众不同，既有传统韵味，又融入了现代元素，令人耳目一新。" },
  { idiom: "独一无二", meaning: "指没有相同的，没有可以相比的。强调唯一性、不可替代，多用于形容事物的独特价值或地位。褒义。", context: "敦煌莫高窟是独一无二的文化艺术宝库，承载着千年文明的记忆。" },
  { idiom: "简明扼要", meaning: "指简单明了、抓住要点，形容说话或写文章简洁明了、重点突出。强调表达简洁、直击核心，多用于形容讲话、文章、报告等精炼准确。褒义。", context: "他的汇报简明扼要，短短十分钟就把项目的来龙去脉和关键问题讲得清清楚楚。" },
  { idiom: "口是心非", meaning: "指嘴上说的是一套，心里想的却是另一套，心口不一。强调言语与内心真实想法不符，多用于批评虚伪、不真诚的态度。贬义。", context: "在批评与自我批评中，要坦诚相待，不能口是心非，当面一套背后一套。" },
  { idiom: "漫不经心", meaning: "指随随便便、不放在心上，形容态度散漫、不认真。强调做事不专心、缺乏重视，多用于批评注意力不集中、不严谨的态度。贬义。", context: "安全生产容不得半点漫不经心，每一个环节都必须全神贯注、认真对待。" },
  { idiom: "虚张声势", meaning: "指假装出强大的声势来吓唬或迷惑对方。强调故意制造声势、夸大实力以图震慑，多用于形容故作姿态、以假乱真的策略。贬义。", context: "这家公司不过是虚张声势，所谓的‘技术突破’并无实质性创新，经不起推敲。" },
  { idiom: "针锋相对", meaning: "指针尖对针尖，比喻双方在策略、论点、行动等方面尖锐对立。强调对立双方势均力敌、互不相让，多用于形容辩论、竞争、冲突中的激烈对峙。中性或贬义。", context: "在辩论赛中，正反双方针锋相对，各抒己见，场面十分激烈。" },
  { idiom: "截然相反", meaning: "指完全相反，毫无共同之处。强调两者之间全然不同、完全对立，多用于形容性质、方向、观点等的彻底对立。中性。", context: "兄弟两人的性格截然相反，一个内向沉稳，一个外向活泼。" },
  { idiom: "纷繁复杂", meaning: "指头绪多而杂乱、情况复杂。强调事物种类繁多、关系交织、难以理清，多用于形容社会现象、问题、局势等的复杂状态。中性。", context: "面对纷繁复杂的国际局势，我们必须保持清醒头脑，沉着应对各种挑战。" },
  { idiom: "指鹿为马", meaning: "指着鹿硬说是马。比喻故意颠倒黑白、混淆是非。强调出于某种目的（如弄权、欺骗）而公然歪曲事实，多用于抨击公然撒谎、混淆视听的恶劣行径。贬义。", context: "在原则问题上，我们必须立场鲜明，绝不容许任何人指鹿为马、颠倒黑白。" },
  { idiom: "削足适履", meaning: "指把脚削小来适应鞋的大小，比喻不顾实际情况，生搬硬套。强调强行迁就、不合理地适应某种标准，多用于批评机械套用、不知变通的做法。贬义。", context: "借鉴国外经验不能削足适履，必须结合本国国情，因地制宜地加以改造。" },
  { idiom: "自欺欺人", meaning: "指既欺骗自己，也欺骗别人。强调明知真相却故意蒙蔽自己和他人，多用于批评掩耳盗铃、自欺欺人的行为。贬义。", context: "在安全问题上，任何自欺欺人的侥幸心理都可能酿成无法挽回的后果。" },
  { idiom: "削峰填谷", meaning: "指削去山峰来填平山谷，比喻调整高低差距、使其均衡。强调平衡差异、调节分配，多用于形容资源调配、能源平衡、收入分配等的均衡措施。中性或褒义。", context: "电力调度系统通过削峰填谷，在用电高峰和低谷之间合理调配，保障了电网的稳定运行。" },
  { idiom: "以管窥天", meaning: "指从竹管里看天，比喻眼界狭小、见识有限，见闻不广。强调视野狭隘、所见有限，与“坐井观天”义近。贬义或自谦。", context: "仅凭局部经验就妄下结论，无异于以管窥天，难以看清全局。" },
  { idiom: "感触", meaning: "指因接触外界事物而引起的思想情绪。强调由外界刺激引发的深层心理反应，往往带有较持久的情感或思考，多用于形容对生活、经历等的内心体悟。名词。", context: "重返故乡，面对旧时的街巷，他心中涌起无限感触。" },
  { idiom: "感悟", meaning: "指有所感触而领悟、觉悟。强调在经历或体验的基础上获得深层理解，带有一定理性认识的升华。名词或动词。", context: "他在基层工作多年，对群众疾苦有了深刻的感悟。" },
  { idiom: "感受", meaning: "指对客观事物或情境产生的心理体验，也指领会、理解。强调通过接触、经历而获得的直接体验或认知，范围较广，既可用于具体感觉，也可用于抽象体验。名词或动词。", context: "参加完这次志愿活动，他深刻感受到了助人为乐的快乐。" },
  { idiom: "感觉", meaning: "指客观事物在人大脑中引起的直接反应，也指觉得、认为。强调感官或心理上的直接印象，是最为基础、直接的感知方式。名词或动词。", context: "走进这座古城，感觉时光都慢了下来。" },
  { idiom: "启示", meaning: "指通过提示或引导而使人有所领悟，也指从某种事物或现象中获得的感悟。强调通过外界事物或言语的提示而获得认识上的突破，多用于形容从自然、事件、作品等中得到的启发。名词或动词。", context: "这部纪录片给观众带来了深刻启示，引发了人们对环境保护的思考。" },
  { idiom: "启蒙", meaning: "指使初学的人获得基本的知识和认识，也指破除迷信、愚昧，使人接受新思想。强调从无到有地开启智慧、传授基础知识，多用于形容教育、文化传播中的基础性引导。动词或名词。", context: "这位乡村教师几十年如一日，为大山里的孩子启蒙，点亮了他们的求知之路。" },
  { idiom: "启发", meaning: "指通过提示、点拨，使对方思考并有所领悟。强调在已有基础上给予引导，使人举一反三、触类旁通，多用于形容教育、交流中的点拨作用。动词。", context: "老师的提问启发了同学们的思考，课堂讨论变得十分活跃。" },
  { idiom: "启迪", meaning: "指启发、开导，使人获得智慧或见识。强调通过引导使人在思想、智慧上有所收获，多用于形容教育、书籍、导师等对人的深远影响。动词，书面语，褒义。", context: "阅读经典著作能启迪心灵，帮助人们树立正确的价值观。" },
  { idiom: "豁免", meaning: "指免除（捐税、劳役等），也指免除法律责任或处罚。强调以权威或法律手段免除本应承担的义务或责任，多用于法律、税务、外交等领域。动词，中性。", context: "根据国际惯例，外交人员享有一定的司法豁免权。" },
  { idiom: "宽恕", meaning: "指宽容饶恕，不计较或原谅对方的过错。强调以宽容之心原谅他人的错误或伤害，多用于道德、情感层面的人际关系。动词，褒义。", context: "面对真诚的道歉，他选择了宽恕，让彼此的关系得以修复。" },
  { idiom: "淡化", meaning: "指使（问题、印象、色彩等）变淡、减轻，使其不突出或不重要。强调有意识地减弱某事物的影响或分量，多用于形容处理问题时的策略性弱化。动词，中性或略带贬义。", context: "面对舆论质疑，他试图淡化事件的严重性，但这种做法反而引发了更多关注。" },
  { idiom: "忽略", meaning: "指没有注意到、疏忽，也指有意不重视、不理会。强调因粗心或不重视而遗漏、忽略，多用于形容对细节、问题等的疏忽。动词，中性或贬义。", context: "在撰写报告时，他忽略了几个关键数据，导致结论出现了偏差。" },
  { idiom: "畏难", meaning: "指害怕困难、不敢面对挑战的心理。强调面对困难时的退缩与恐惧，多用于形容在挑战面前缺乏勇气和信心。动词或名词，贬义或中性。", context: "学习新技能时不能畏难，只要勇敢迈出第一步，就会发现并没有想象中那么难。" },
  { idiom: "紧张", meaning: "指精神或肌肉处于高度绷紧状态，也指局势、关系等不宽松、不缓和。强调压力下的紧绷感，多用于形容心理状态、人际氛围或局势态势。形容词或名词，中性。", context: "面试前他感到有些紧张，但深呼吸几次后逐渐平静了下来。" },
  { idiom: "侥幸", meaning: "指企求意外地获得成功或免去不幸，也指因偶然因素取得成功而庆幸。强调寄希望于运气、不靠实力，多用于形容投机取巧的心理。名词或形容词，贬义或中性。", context: "安全生产容不得半点侥幸心理，必须严格遵守操作规程。" },
  { idiom: "抵触", meaning: "指对某种事物或要求产生反感、不认同的情绪，也指矛盾冲突。强调内心的不认同或抗拒，多用于形容对政策、规定、建议等的负面态度。动词或名词，贬义或中性。", context: "部分群众对这项新政策产生了抵触情绪，需要加强宣传引导，争取理解与支持。" },
  { idiom: "琢磨", meaning: "指反复思考、仔细推敲，也指对玉石等进行加工打磨。强调深入思考、精细研究的过程，多用于形容对问题、文章、作品等的反复斟酌。动词，褒义或中性。", context: "这篇文章他还需要再琢磨一下，把用词和逻辑打磨得更精准。" },
  { idiom: "捉摸", meaning: "指猜测、揣度，多用于否定式“捉摸不定”。强调对人或事物的意图、变化等进行猜测和推断，多用于形容难以预料、难以把握的状态。动词，中性。", context: "他这个人性格古怪，喜怒无常，让人捉摸不透。" },
  { idiom: "商榷", meaning: "指商量讨论、交换意见，多用于学术或正式场合的商讨。强调以平等、理性的态度就某一问题进行探讨，多用于书面语。动词，中性或褒义。", context: "关于这一历史事件的成因，学术界仍有待进一步商榷和论证。" },
  { idiom: "气度", meaning: "指人的气魄和度量，也指举止、风度。强调胸襟开阔、包容大度，多用于形容人在待人接物时的豁达与从容。名词，褒义。", context: "这位老领导气度不凡，面对批评既能虚心接受，又能坚持原则，令人敬佩。" },
  { idiom: "气概", meaning: "指在重大问题上表现出的豪迈气魄和坚定态度。强调面对困难或挑战时的勇毅和胆识，多用于形容英雄人物或革命者的豪情壮志。名词，褒义。", context: "革命先烈以气概豪迈的英雄气概，书写了可歌可泣的历史篇章。" },
  { idiom: "气质", meaning: "指人的内在修养、性格特征所外显出的独特风格和韵味。强调由内而外、长期养成的人格魅力，多用于形容人的内在修养和外在风度的统一。名词，褒义或中性。", context: "这位舞蹈家气质优雅，举手投足间尽显艺术家的风范。" },
  { idiom: "气派", meaning: "指事物或场所显示出的气势、规模，也指人的排场和风度。强调外在的宏大、豪华或威仪，多用于形容建筑、场所、场景等的气势不凡。名词，褒义或中性。", context: "这座新建的博物馆气派宏伟，是城市的新地标。" },
  { idiom: "难以为继", meaning: "指无法再继续下去。强调因缺乏条件或支撑而难以维持，多用于形容事业、项目、生计等的持续性受挫。中性偏贬义。", context: "由于资金链断裂，该项目的研发工作已难以为继，面临停工风险。" },
  { idiom: "步履维艰", meaning: "指行走十分困难，比喻做事或前进的过程极为艰难。强调每一步都很不容易，多用于形容在困境中缓慢前行的状态。贬义或中性。", context: "这家企业在市场竞争中步履维艰，面临着成本上升和需求下滑的双重压力。" },
  { idiom: "寸步难行", meaning: "指一步都走不了，比喻处境非常困难、无法行动。强调因外部阻力或条件限制而完全无法前进，多用于形容遭受严重阻碍的状态。贬义。", context: "没有当地群众的支持，扶贫工作队在这里寸步难行。" },
  { idiom: "一筹莫展", meaning: "指一点办法也想不出，毫无对策。强调面对问题或困境时完全无计可施、束手无策，多用于形容遇到难题时的无奈状态。贬义或中性。", context: "面对突如其来的技术故障，工程师们一度一筹莫展，最终在多方协作下才找到解决方案。" },
  { idiom: "圭臬", meaning: "指古代测定日影的仪器，比喻准则、法度或典范。强调被奉为最高标准或不可动摇的原则，多用于形容思想、理论、原则等被尊崇的地位。名词，书面语，褒义或中性。", context: "实事求是是党的思想路线的圭臬，贯穿于各项工作的始终。" },
  { idiom: "圣旨", meaning: "原指古代皇帝发布的诏令，现多比喻不容违抗的命令或权威指示。强调具有绝对权威、不可违背，多用于形容强硬的指令或不容置疑的要求，常含讽刺意味。名词，贬义或中性（戏谑语境）。", context: "企业决策不能像下圣旨一样单方面强推，而要充分听取员工的意见。" },
  { idiom: "准则", meaning: "指言行、思想等所依据的原则或标准。强调作为判断依据的规范、标准，多用于形容道德、法律、行为等方面的规则。名词，中性或褒义。", context: "诚信是市场经济运行的基本准则，任何企业都不能违背。" },
  { idiom: "信条", meaning: "指信仰或信奉的纲领、原则、理念等。强调个人或群体坚信并遵行的理念，多用于形容价值观、人生信念等方面的坚守。名词，中性或褒义。", context: "“为人民服务”是中国共产党人的根本信条，代代相传、始终如一。" },
  { idiom: "警戒", meaning: "指为防备可能发生的问题而保持警觉、严加防备的状态，也指军队等为防备敌人而采取的守卫措施。强调持续的防范状态、严加戒备，常与“线”“状态”“部队”等搭配。动词或名词，中性。", context: "警方在事故路段设置了警戒线，禁止无关车辆进入。" },
  { idiom: "警报", meaning: "指通过声音、信号等发出的危险或紧急情况的提醒，也指对危机的预警。强调通过特定信号向公众传达紧急信息，多用于防空、防灾、安全等领域。名词，中性。", context: "地震警报响起后，全校师生迅速有序地撤离到了安全地带。" },
  { idiom: "警示", meaning: "指通过事例、标志等提醒人们注意潜在危险或问题，使人警惕。强调通过某种形式（如标志、案例、教训）唤起警觉，常与“标志”“作用”“意义”等搭配。动词或名词，中性或褒义。", context: "这座事故遗址作为警示教育基地，提醒后人时刻重视安全生产。" },
  { idiom: "警告", meaning: "指提醒、告诫，使其注意并改正，也指对错误行为的正式告诫或处分。强调明确的言语或行为告诫，带有一定程度的严厉性，多用于劝诫或纪律处分。动词或名词，中性。", context: "该球员因恶意犯规被裁判出示黄牌警告。" },
  { idiom: "采集", meaning: "指收集、采录，多用于自然物或数据资料的搜集。强调从自然或现场获取原始材料，多用于动植物标本、矿石、样本、数据等的收集。动词，中性。", context: "科研人员在野外采集了大量的植物标本，为后续研究提供了宝贵的第一手资料。" },
  { idiom: "汇集", meaning: "指从不同方向、地点聚集到一起，强调分散的事物向中心靠拢、集中，多用于人群、力量、资源、信息等的聚集。动词。", context: "来自全国各地的游客汇集在广场上，共同庆祝节日。" },
  { idiom: "收集", meaning: "指把分散的事物搜罗、聚集起来。强调主动地、有目的地把散落的事物集中到一起，使用范围较广，可用于信息、资料、物品等。动词，中性。", context: "环保志愿者在河岸边收集塑料垃圾，用实际行动守护母亲河。" },
  { idiom: "搜集", meaning: "指到处寻找并聚集，强调搜寻与收集的结合，比“收集”更强调寻找的过程和难度。多用于信息、证据、资料、文物等需要主动搜寻的事物。动词，中性。", context: "警方正在全力搜集犯罪证据，争取尽快破案。" },
  { idiom: "牵强附会", meaning: "指把关系不大的事物勉强地扯在一起，生拉硬拽地加以联系。强调不顾事实地强行关联、勉强凑合，多用于批评论证或解释中的强词夺理。贬义。", context: "这种将两个毫无关联的事件强行联系在一起的说法，未免过于牵强附会，难以令人信服。" },
  { idiom: "曲意逢迎", meaning: "指违背自己的本意，千方百计地迎合讨好别人。强调了讨好他人而刻意迎合、阿谀奉承，多用于批评谄媚取宠、丧失原则的行为。贬义。", context: "真正的朋友应该是直言相谏，而不是曲意逢迎、一味迎合你的错误。" },
  { idiom: "偷梁换柱", meaning: "比喻暗中玩弄手法，以假代真，以次充好。强调以隐蔽手段偷换关键内容、混淆视听，多用于形容欺诈、作弊、篡改等恶劣行为。贬义。", context: "这家公司通过偷梁换柱的方式修改合同条款，损害了消费者的合法权益。" },
  { idiom: "附庸风雅", meaning: "指为了装点门面而结交名士、从事文化活动，以显示自己高雅。强调本无真才实学却故作高雅、装点门面，多用于批评虚荣做作的行为。贬义。", context: "他买了很多名著摆在书架上，却一本也没读过，不过是附庸风雅罢了。" },
  { idiom: "劳民伤财", meaning: "指既使百姓劳苦，又耗费钱财。强调工程或活动给民众带来负担、浪费资源，多用于批评不切实际、铺张浪费的政绩工程或项目。贬义。", context: "这类不切实际的形象工程，不仅劳民伤财，还严重浪费了公共资源，必须坚决叫停。" },
  { idiom: "无所适从", meaning: "指不知道依从谁好，不知道怎么办才好。强调选择过多或方向不明而导致的困惑、茫然，多用于面对矛盾要求或多重选择时的状态。贬义。", context: "各部门意见不一，基层执行时常常无所适从，影响了工作效率。" },
  { idiom: "皈依", meaning: "原指佛教的入教仪式，后泛指虔诚地信奉某种宗教或思想。强调身心归附、虔诚信奉，多用于宗教信仰或精神追求的语境。动词，书面语，中性或褒义。", context: "他在经历了人生的起伏后，最终皈依了内心的宁静，选择了简朴而充实的生活方式。" },
  { idiom: "抚慰", meaning: "指用言语或行动安慰、安抚，使心情平静。强调通过温情的关怀抚平对方的心灵创伤或不安，多用于情感层面的安慰。动词，褒义。", context: "社区工作者耐心地抚慰受灾群众的情绪，帮助他们重建生活信心。" },
  { idiom: "寄托", meaning: "指把理想、希望、感情等放在某人或某物上，也指托付、安放。强调将抽象的情感或期望安放于具体的人或事物上，多用于形容精神上的依靠。动词或名词，褒义或中性。", context: "这座老宅寄托着祖辈几代人的情感记忆，是他们心中永远的家。" },
  { idiom: "慰藉", meaning: "指安慰、抚慰，使内心得到宽慰和安宁。强调在精神上给予抚慰，使人从忧伤、失落中获得平静，多用于书面语，比“抚慰”更侧重精神层面。动词或名词，褒义。", context: "阅读经典文学作品，能给人带来心灵的慰藉，让人在浮躁的社会中找到片刻安宁。" },
  { idiom: "崇拜", meaning: "指尊敬钦佩、奉为榜样，多用于对英雄、伟人、神明等的敬仰。强调因崇敬而仰慕，带有理性的尊敬感，多用于正面或宗教语境。动词或名词，褒义或中性。", context: "这位科学家毕生致力于科研事业，深受青年学子的崇拜和敬仰。" },
  { idiom: "痴迷", meaning: "指对某人或某事物极度迷恋、沉醉其中，不能自拔。强调因喜爱而沉迷，多用于对艺术、兴趣、偶像等的极度投入，程度较重。动词或形容词，中性或略带贬义（视语境而定）。", context: "他对古琴艺术痴迷多年，每日抚琴不辍，技艺日渐精进。" },
  { idiom: "眷恋", meaning: "指对某人、某地或某段经历深情怀念、依依不舍。强调情感上的深厚依恋和不舍，多用于对故乡、亲人、旧时光的深切感情。动词或名词，褒义。", context: "离开故乡多年，他依然眷恋着那片生他养他的土地和淳朴的乡音。" },
  { idiom: "痴狂", meaning: "指极度迷恋到近乎疯狂的程度，强调情感或行为的失控、极端投入，多用于形容对艺术、爱情、理想等的狂热追求，程度重于“痴迷”。形容词，中性或略带贬义。", context: "他对音乐的痴狂近乎偏执，为了一个音符可以反复推敲几十遍。" },
  { idiom: "无迹可寻", meaning: "指没有踪迹可寻找，形容事物消失得无影无踪或难以发现。强调不留下任何线索或痕迹，多用于形容消失、隐藏或难以追查的状态。中性。", context: "这场大雾来得快去得也快，待到日出时分，昨夜弥漫的浓雾早已无迹可寻。" },
  { idiom: "变化莫测", meaning: "指事物变化多端，难以预测。强调变化复杂且无法捉摸，无法预料其走向，多用于形容天气、命运、局势等。中性。", context: "高原天气变化莫测，刚才还是晴空万里，转眼间狂风大作。" },
  { idiom: "难以捉摸", meaning: "指不容易猜测、把握或理解。强调人或事物的特征、意图、变化等难以被准确判断，多用于形容性格、感觉、局势等。中性或略带贬义。", context: "他的情绪总是难以捉摸，刚才还谈笑风生，转眼就沉默不语。" },
  { idiom: "推脱", meaning: "指推卸、开脱（责任、义务等），强调设法使自己不承担应负的责任或义务。多用于形容在面对职责、过错、任务等时故意避开或转嫁给他人的行为。动词，贬义或中性。", context: "面对群众的合理诉求，相关部门不能推脱责任，必须主动作为、积极解决。" },
  { idiom: "推托", meaning: "指借故拒绝、推辞，强调以某种理由或借口回避或婉拒某项事情。多用于形容以理由搪塞、不愿接受任务或要求的行为。动词，贬义或中性。", context: "面对采访邀请，他推托自己工作繁忙，婉言谢绝了记者的请求。" },
  { idiom: "若隐若现", meaning: "形容隐隐约约、看不真切，时而显现时而隐没。强调视觉上的模糊、不清晰，多用于形容远处的景物、记忆中的画面等模糊状态。中性。", context: "晨雾中，远处的山峰若隐若现，宛如一幅水墨画，令人心驰神往。" },
  { idiom: "跃然纸上", meaning: "形容文学作品或绘画生动逼真，仿佛活了一样呈现在纸上。强调刻画生动、形象鲜明，让读者或观者如见其人、如临其境，多用于形容描写、刻画的高超技艺。褒义。", context: "作者通过细腻的笔触，将主人公的喜怒哀乐跃然纸上，读来令人动容。" },
  { idiom: "昭然若揭", meaning: "指真相或事实完全暴露出来，非常明显、清清楚楚。强调隐秘的事情暴露无遗，任何人都看得清楚，多用于形容谎言、阴谋、真相的彻底败露。褒义或中性。", context: "在铁证面前，对方的谎言昭然若揭，再也无法辩解。" },
  { idiom: "露出马脚", meaning: "指隐秘的真相或破绽暴露出来，多含贬义，常用于形容欺诈行为或秘密计划被揭穿。名词性短语，贬义或中性。", context: "骗子编造的谎言看似天衣无缝，但细节处还是露出马脚，被细心的民警当场识破。" },
  { idiom: "灰飞烟灭", meaning: "比喻事物消失殆尽，化为乌有。强调彻底灭亡、消失得无影无踪，多用于形容希望、理想、势力等的彻底破灭。贬义或中性。", context: "任何违背历史潮流的反动势力，终将在人民的意志面前灰飞烟灭。" },
  { idiom: "烟消云散", meaning: "比喻事物消失净尽，不留痕迹。强调像烟云一样消散无存，多用于形容疑虑、隔阂、记忆、情绪等的消失。中性。", context: "误会澄清后，两人之间的隔阂终于烟消云散，关系重归于好。" },
  { idiom: "一览无余", meaning: "指一眼望去，全部景象都尽收眼底，没有遗漏。强调视野开阔、全部景象都能看到，多用于形容登高远眺时的开阔视野。褒义或中性。", context: "站在山顶俯瞰，整个城市的美景一览无余，令人心旷神怡。" },
  { idiom: "一览而尽", meaning: "指一眼望去就全部看到、全部了解。强调快速全面地把所有内容看完、了解完，多用于形容快速阅读或浏览。中性。", context: "这篇短文篇幅不长，内容简洁，一览而尽，却意味深长。" },
  { idiom: "一目千里", meaning: "原形容视力极好，能看清千里之外的事物，现多比喻目光远大、有远见，也有形容阅读速度极快的意思。强调视野宽广、高瞻远瞩，多用于形容眼光长远或快速阅读。褒义或中性。", context: "真正的战略家应具备一目千里的远见，能够洞察未来的发展趋势。" },
  { idiom: "眺望", meaning: "指从高处或远处往远处看。强调登高望远、视野开阔，多用于形容欣赏风景、观察远方。动词，中性或褒义。", context: "站在古城墙上眺望远方，青山如黛，江水如练，景色美不胜收。" },
  { idiom: "目睹", meaning: "指亲眼看到、亲眼所见。强调亲眼在场、直接见证，多用于形容亲身经历或亲见重要事件。动词，中性。", context: "他亲眼目睹了这座城市的巨变，从破旧的街巷到高楼林立，感慨万千。" },
  { idiom: "捕捉", meaning: "原指捕捉动物，现也比喻抓住、发现不易察觉的事物（如机会、眼神、镜头瞬间）。强调主动捕捉、敏锐抓取，多用于形容摄影、观察、记录等场景。动词，中性或褒义。", context: "摄影师用镜头捕捉了孩子们纯真灿烂的笑容。" },
  { idiom: "观测", meaning: "指观察并测量，多用于天文、气象、地理等领域的科学观察。强调结合观察与测量，以获得准确数据，多用于科学研究、环境监测等。动词，中性。", context: "气象卫星从太空观测地球大气变化，为天气预报提供了重要数据。" },
  { idiom: "不遗余力", meaning: "指把全部力量都使出来，毫不保留。强调竭尽全力、不留余地，多用于形容面对重要任务时的态度和行动。褒义。", context: "科研团队不遗余力地攻关，终于在deadline前完成了这项艰巨的研发任务。" },
  { idiom: "分毫不差", meaning: "形容非常准确、精确，没有一点误差。强调精确度极高，多用于描述测量、计算、模仿等方面的精准。褒义。", context: "他凭着多年的经验，估算出来的数据与实际结果分毫不差。" },
  { idiom: "滴水不漏", meaning: "形容说话、办事周密严谨，毫无疏漏。强调考虑周全、毫无破绽，多用于形容措辞严谨或安排周详。褒义。", context: "他的方案设计得滴水不漏，每一个细节都考虑到了，让评审团无可挑剔。" },
  { idiom: "当务之急", meaning: "指当前最急切、最要紧的事情。强调紧迫性、优先性，多用于形容当前必须优先处理的事项。中性。", context: "解决人民群众的急难愁盼问题是当务之急，必须抓紧落实、尽快见效。" },
  { idiom: "万全之策", meaning: "指极其周全、毫无纰漏的计策或办法。强调策略的完备性和可靠性，多用于形容经过周密考虑、可以确保万无一失的方案。褒义。", context: "面对复杂的市场环境，管理层正在寻找万全之策，既保证业务增长，又控制风险。" },
  { idiom: "真知灼见", meaning: "指正确而深刻的认识和见解。强调见解正确、透彻，多用于形容对问题有深刻把握、切中要害的观点。褒义。", context: "他在论坛上发表的真知灼见，引发了许多专家学者的深入思考和热烈讨论。" },
  { idiom: "远见卓识", meaning: "指远大的眼光和高明的见识。强调眼界开阔、见解高明，多用于形容领导者或战略家的前瞻性判断能力。褒义。", context: "正是得益于这位企业家的远见卓识，公司在行业发展初期就布局了AI技术，如今已占据领先地位。" },
  { idiom: "肺腑之言", meaning: "指发自内心的真诚话语。强调真诚恳切、出自真心，多用于形容发自内心、没有虚伪的言语。褒义。", context: "他在退休前的最后一次讲话，句句都是肺腑之言，令在场所有人深受感动。" },
  { idiom: "齐心协力", meaning: "指大家思想一致、共同努力。强调团结合作、心往一处想、劲往一处使，多用于形容集体行动中的团结协作。褒义。", context: "面对突如其来的灾情，军民齐心协力，共同筑起了守护家园的坚固防线。" },
  { idiom: "有的放矢", meaning: "比喻说话做事有明确的目的和针对性。强调目标明确、不盲目行动，与“无的放矢”相对，常与“精准施策”“对症下药”等搭配使用。褒义。", context: "新时代新征程，我们只有深刻理解把握这一总目标，才能有的放矢、精准发力。" },
  { idiom: "销声匿迹", meaning: "指隐藏起来，不公开露面，不再公开出现。强调完全消失、不再出现，多用于形容人或事物从公众视野中彻底消失。中性或略带贬义。", context: "这起风波过后，那位曾经红极一时的网红便销声匿迹，再未出现在公众视野中。" },
  { idiom: "后继无人", meaning: "指没有后来接替前人的事业。强调传承断裂、缺乏接班人，多用于形容技艺、事业、人才等的断层困境。贬义。", context: "这门传统手工艺因工艺复杂、收入微薄，面临后继无人的困境，急需保护与传承。" },
  { idiom: "高高在上", meaning: "原指地位高，现多形容领导者脱离实际、脱离群众，不深入基层。强调有距离感、不亲近群众，带有批评意味。贬义。", context: "领导干部要深入基层调查研究，切忌高高在上、脱离实际。" },
  { idiom: "空空如也", meaning: "形容空空的，什么都没有。强调内部空无一物、一无所有，多用于形容容器、空间、房间等的空旷状态。中性。", context: "打开冰箱一看，空空如也，这才想起来已经好几天没去超市了。" },
  { idiom: "一尘不染", meaning: "原指佛教徒修行时排除物欲、保持心地洁净，现多形容环境非常清洁、干净。强调洁净无暇、干净整洁，多用于形容房间、器物等的清洁状态，也形容人品格高洁。褒义。", context: "这间老屋虽然陈设简单，却被主人收拾得一尘不染，窗明几净。" },
  { idiom: "老调重弹", meaning: "指把陈旧的理论或主张重新拿出来说，没有新内容。强调重复过时的、毫无新意的话，多用于批评言论陈旧、缺乏创新。贬义。", context: "他的发言不过是老调重弹，翻来覆去还是那几句老话，没有任何新意。" },
  { idiom: "根深蒂固", meaning: "比喻基础深厚、不容易动摇。强调观念、习惯、传统等深深扎根、难以改变，多用于形容思想、习俗、弊端等的顽固性。中性或略带贬义。", context: "在一些偏远地区，重男轻女的陈旧观念依然根深蒂固，需要长期的教育引导才能逐步改变。" },
  { idiom: "渐入佳境", meaning: "指逐渐进入美好的境地，形容情况或状态越来越好。强调持续向好、逐步改善的过程，多用于形容工作、生活、比赛等的状态不断提升。褒义。", context: "经过初期的磨合，球队配合愈发默契，比赛状态渐入佳境，连战连捷。" },
  { idiom: "稳操胜券", meaning: "指有把握取得胜利。强调胜算极大、胜券在握，多用于形容在竞争、比赛、谈判等中有十足把握取胜。褒义。", context: "决赛前，全队士气高涨、信心十足，教练表示对夺冠稳操胜券。" },
  { idiom: "废寝忘食", meaning: "指顾不上睡觉、忘记了吃饭，形容非常专心努力。强调极度专注、全身心投入，多用于形容工作、学习或研究时的投入状态。褒义。", context: "为了攻克技术难关，他常常废寝忘食，工作到深夜。" },
  { idiom: "呕心沥血", meaning: "指费尽心血，形容为工作或事业极度操劳、耗费巨大心力。强调付出巨大的心血和精力，多用于形容创作、教育、科研等需要长期投入的工作。褒义。", context: "这位作家呕心沥血三十载，终于完成了这部百万字的史诗巨著。" },
  { idiom: "苦心孤诣", meaning: "指费尽心思、专心致志，在学问或技艺上达到他人难以企及的境界。强调用心良苦、钻研至深，多用于形容在学术、艺术等领域的深入钻研。褒义。", context: "他在古琴演奏上苦心孤诣数十年，形成了独具特色的演奏风格。" },
  { idiom: "精益求精", meaning: "指在好的基础上追求更好。强调不满足于已有成绩、不断追求更高的境界和质量，多用于形容对技艺、产品、工作等的极致追求。褒义。", context: "工匠精神的核心就是精益求精，对每一个细节都追求极致完美。" },
  { idiom: "杀鸡取卵", meaning: "比喻只顾眼前利益而牺牲长远利益，像杀了鸡去取蛋一样愚蠢。强调目光短浅、因小失大，多用于批评只图眼前好处而损害长远发展的行为。贬义。", context: "过度开采矿产资源无异于杀鸡取卵，虽然换来了短期收益，却给子孙后代留下了生态灾难。" },
  { idiom: "唯利是图", meaning: "指只贪图利益，不顾及其他一切。强调以利益为唯一追求目标，不讲道义、不计后果，多用于批评贪婪无度的行为。贬义。", context: "这些唯利是图的商家不惜以次充好、欺骗消费者，最终必将受到法律严惩。" },
  { idiom: "暴殄天物", meaning: "指任意糟蹋东西，不知爱惜。强调对物品、资源等肆意浪费、不加珍惜，多用于批评浪费粮食、资源的行为。贬义。", context: "大量未售出的食品被直接销毁，如此暴殄天物的行为引发了社会对食物浪费问题的高度关注。" },
  { idiom: "无能为力", meaning: "指没有能力或力量去做好某事，多指因客观条件限制而无法施展。强调受自身能力或外部条件制约而无法发挥作用，多用于形容在困难面前的无奈。贬义或中性。", context: "看着灾区的废墟，他感到无能为力，但很快就振作起来，加入到了救援队伍中。" },
  { idiom: "苦不堪言", meaning: "指痛苦到了极点，无法用言语来表达。强调承受的苦难或压力极为深重，多用于形容极端困苦、难以承受的状态。贬义。", context: "连日来的高温天气让户外工作者苦不堪言，各地纷纷设立了避暑纳凉点。" },
  { idiom: "不屑一顾", meaning: "认为不值得一看，形容极端轻视。强调看不起、完全不放在眼里，多用于对某人、某物或某种行为的鄙视态度。贬义。", context: "对于这种低俗的网络直播内容，真正的艺术家们不屑一顾。" },
  { idiom: "嗤之以鼻", meaning: "用鼻子吭气，表示看不起。强调极度轻蔑、不屑一顾的态度，多用于对某人或某事的轻视与否定。贬义。", context: "对于这种毫无根据的谣言，真正的科学家只会嗤之以鼻。" },
  { idiom: "粗制滥造", meaning: "指制作工艺粗糙、质量低劣，不顾质量地大量制造。强调产品品质差、做工马虎，多用于批评产品质量不过关、敷衍了事的生产行为。贬义。", context: "一些商家为了降低成本，粗制滥造，将劣质产品投入市场，严重损害了消费者权益。" },
  { idiom: "差强人意", meaning: "指大体上还能让人满意，表示勉强过得去。强调虽然不算完美，但基本满足要求，尚可接受。褒义或中性（注意：常被误用为“不能让人满意”，实际意为“尚可满意”）。", context: "虽然球队表现不算惊艳，但整体发挥差强人意，成功晋级下一轮。" },
  { idiom: "眼花缭乱", meaning: "指眼睛看到复杂纷繁的事物而感到迷乱，形容事物繁多、色彩斑斓，令人目不暇接。强调事物丰富多样、让人看不过来，多用于形容商品、景象、信息等的繁多。中性或褒义。", context: "展会上各种新产品琳琅满目，让人眼花缭乱，充分展现了科技创新的活力。" },
  { idiom: "名不副实", meaning: "指名称或名声与实际不相符合。强调徒有虚名、名实不符，多用于批评有名无实、空有其表的人或事物。贬义。", context: "这家餐厅被曝卫生极差，名不副实，令消费者大失所望。" },
  { idiom: "捕风捉影", meaning: "比喻说话或做事时用似是而非的迹象做根据，不切实际。强调言行缺乏事实依据，凭空猜测或捏造。贬义。", context: "这些关于产品安全问题的传言纯属捕风捉影，企业已向公安机关报案。" },
  { idiom: "自以为是", meaning: "指认为自己总是正确的，形容主观、不虚心。强调主观狂妄，拒绝接受他人观点。贬义。", context: "领导干部如果总是自以为是，听不进群众意见，就会脱离实际。" },
  { idiom: "随心所欲", meaning: "指随着自己的心意，想怎样就怎样。强调不受约束、自由行事，多用于形容自由自在的状态，也可含贬义指任意妄为。中性或略带贬义（视语境而定）。", context: "在艺术创作中，他随心所欲地挥洒笔墨，作品中充满了天马行空的想象力。" },
  { idiom: "偃旗息鼓", meaning: "指放倒军旗、停止击鼓，原指军队隐蔽行动或停止作战，现比喻事情中止或声势减弱。强调由盛转衰、暂停行动或不再张扬，多用于形容活动、运动、争论等的平息。中性。", context: "这场持续数月的舆论风波终于偃旗息鼓，公众的注意力逐渐转向了其他话题。" },
  { idiom: "危在旦夕", meaning: "指危险就在眼前，形容情况极其危急，随时可能发生不测。强调危险迫在眉睫、刻不容缓，多用于形容生命、安全、局势等的极度危急状态。贬义。", context: "洪水已经漫过堤坝，下游村庄危在旦夕，救援队伍正在与时间赛跑。" },
  { idiom: "望尘莫及", meaning: "指远远望着前面人马扬起的尘土而追赶不上，比喻远远落后、无法企及。强调差距极大、难以赶上，多用于形容能力、水平、成就等方面的悬殊差距。中性或略带贬义。", context: "在芯片制造领域，国内企业与国际巨头相比仍有较大差距，短期内望尘莫及。" },
  { idiom: "日渐式微", meaning: "指逐渐衰落、一天不如一天。强调事物持续走向衰落，多用于形容传统技艺、行业、文化等的逐渐衰退。贬义或中性。", context: "随着智能手机的普及，传统手表的计时功能日渐式微，转而向装饰和时尚方向转型。" },
  { idiom: "融合", meaning: "指不同的事物或元素相互渗透、合为一体，形成新的整体。强调融为一体、界限消失，多用于形容文化、思想、技术、艺术等方面的深度交融。动词或名词，褒义。", context: "这部作品融合了传统戏曲与现代音乐的元素，呈现出独特的艺术风格。" },
  { idiom: "回合", meaning: "原指古代双方交战、互相攻击一次叫一个回合，现比喻双方较量、辩论的来回。强调交替较量的过程，多用于形容比赛、谈判、辩论中的来回交锋。名词，中性。", context: "经过多个回合的磋商，双方终于就合作细节达成了一致。" },
  { idiom: "结合", meaning: "指两个或多个事物紧密联系起来，形成统一体。强调相互关联、结合在一起，多用于形容理论联系实际、资源整合等方面。动词或名词，中性或褒义。", context: "理论学习要同实践紧密结合，真正做到学以致用、知行合一。" },
  { idiom: "综合", meaning: "指将不同事物或各方面的内容汇总、归纳，形成一个整体。强调汇总整合、全面统筹，多用于形容分析、评价、规划等的全面性和系统性。动词或形容词，中性或褒义。", context: "我们要综合考虑经济、社会、环境等多方面因素，制定科学合理的发展规划。" },
  { idiom: "特立独行", meaning: "指有操守、有见识，不随波逐流。强调行为独特、不盲从流俗，多含褒义，用于形容人格独立、坚持自我。褒义。", context: "他一生特立独行，不为世俗所动，始终坚持自己的艺术追求。" },
  { idiom: "循规蹈矩", meaning: "指遵守规矩、不越轨，形容拘守成规、不敢稍有变动。强调严格遵守规则和传统，多用于形容行为谨慎守旧。中性或略带贬义（视语境而定）。", context: "在强调创新的时代，如果一味循规蹈矩，就难以在激烈的竞争中脱颖而出。" },
  { idiom: "犬牙交错", meaning: "形容交界处参差不齐、互相交错，像狗牙那样不整齐。强调边界线曲折交错、互有穿插，多用于形容地形、边界、势力范围的错综复杂格局。中性。", context: "两国边境线犬牙交错，历史上多次因边界划界问题产生争议。" },
  { idiom: "栉风沐雨", meaning: "指以风梳发、以雨洗头，形容在外奔波劳碌、不避风雨的艰辛。强调长途跋涉、历经风吹雨打的辛苦状态，多用于形容劳动者、建设者、旅行者等在艰苦环境下的坚持与付出。褒义。", context: "一代代建设者栉风沐雨，在荒原上建起了一座现代化城市。" },
  { idiom: "妙手偶得", meaning: "指文学素养深的人偶然间即可得到佳句，形容技艺高超的人灵感一来便能写出绝妙之作。强调灵感与功底的结合、偶然中见必然，多用于形容文艺创作中的神来之笔。褒义。", context: "这首小诗看似信手拈来，实则是诗人多年积累后的妙手偶得。" },
  { idiom: "一蹴而就", meaning: "指踏一步就成功，形容事情轻而易举，一下子就能完成。强调过程短暂、毫不费力，多用于否定句中，说明成就需要长期积累，不能急于求成。中性（多用于否定）。", context: "科技创新不可能一蹴而就，需要长期投入和持续攻关。" },
  { idiom: "灵机一动", meaning: "指突然想出一个主意，形容思维敏捷、忽然产生灵感。强调在瞬间迸发的巧妙想法，多用于形容解决问题的机智反应。中性或褒义。", context: "面对突发状况，他灵机一动，用随身携带的工具临时搭起了一个简易支架。" },
  { idiom: "明哲保身", meaning: "原指明智的人善于保全自己，现多指因怕犯错误或得罪人而回避斗争、保全个人利益。强调处事圆滑、回避是非，多含贬义，用于批评不顾原则、只求自保的态度。贬义或中性（视语境而定）。", context: "面对不正之风，党员干部不能明哲保身，而应敢于斗争、坚守原则。" },
  { idiom: "自力更生", meaning: "指不依赖外力，靠自己的力量把事情办起来。强调自主奋斗、不依赖外援，多用于形容国家、民族、集体或个人在困难条件下靠自身努力求发展。褒义。", context: "老一辈科学家自力更生、艰苦奋斗，在极其困难的条件下研制出了‘两弹一星’。" },
  { idiom: "独善其身", meaning: "原指独自修养身心、保持个人节操，现多指只顾自己、不关心他人或集体。强调洁身自好或只顾自身，多含贬义，用于批评缺乏社会责任感的态度。中性或略带贬义（视语境而定）。", context: "青年不能只独善其身，而应将个人理想融入国家发展大局。" },
  { idiom: "自给自足", meaning: "指依靠自己的生产满足自己的需要。强调经济上不依赖外界、能自我供给，多用于形容小农经济、封闭经济体或个人的独立状态。中性。", context: "过去，这个偏远山村几乎与世隔绝，过着自给自足的生活。" },
  { idiom: "如数家珍", meaning: "比喻对所讲的事情十分熟悉，像数自己家里的珍宝一样清楚。强调了解透彻、烂熟于心，多用于形容对事物细节的熟悉程度。褒义。", context: "这位老馆长对馆内每一件文物的来历都如数家珍，讲起来滔滔不绝。" },
  { idiom: "了如指掌", meaning: "形容对情况非常清楚，像指着自己的手掌给人看一样。强调了解得极其清楚、没有任何疑问，多用于形容对情况、过程、问题等的清晰把握。褒义。", context: "他对这一带的地形了如指掌，因此在搜救行动中发挥了关键作用。" },
  { idiom: "念念不忘", meaning: "指牢记在心，时刻不忘。强调对某人或某事印象极深、牵挂不已，多用于形容深切的思念或持久的牵挂。中性或褒义。", context: "他始终念念不忘家乡的山水和亲人，大学毕业后毅然选择回乡创业。" },
  { idiom: "迫在眉睫", meaning: "指事情临近眼前，形容形势非常紧迫。强调时间紧急、必须立即应对，多用于形容危机、任务、决策等的紧迫性。中性或略带贬义。", context: "汛期将至，防汛工作迫在眉睫，各地必须提前做好应急准备。" },
  { idiom: "千头万绪", meaning: "指事情的头绪非常多，形容事物复杂纷乱。强调事务繁多、条理不清，多用于形容工作、问题、思绪等的繁杂状态。中性或略带贬义。", context: "基层工作千头万绪，必须分清主次、统筹安排，才能有条不紊地推进。" },
  { idiom: "千难万险", meaning: "指经历了无数艰难险阻。强调困难重重、险阻极多，多用于形容奋斗历程、创业道路等的艰难困苦。贬义或中性。", context: "红军长征历经千难万险，最终胜利到达陕北，创造了人类历史上的伟大奇迹。" },
  { idiom: "万无一失", meaning: "指非常有把握，绝对不会出差错。强调周密准备、毫无疏漏，多用于形容计划、安排或安保措施极其稳妥。褒义。", context: "航天发射任务必须做到万无一失，每一个环节都要反复检查确认。" },
  { idiom: "立竿见影", meaning: "指在阳光下竖起竹竿，立刻就能看到影子，比喻见效极快。强调措施实施后迅速产生效果，多用于形容政策、方法、药物等的快速见效。中性或褒义。", context: "这项惠企政策立竿见影，实施当月就为企业减负数十亿元。" },
  { idiom: "齐头并进", meaning: "指不分先后地一齐前进，形容几方面同时进行、共同发展。强调同步推进、不相上下，多用于形容多项工作、多个领域、多支队伍的共同推进。褒义。", context: "在推进新型城镇化的过程中，经济建设与生态保护应齐头并进，不可偏废。" },
  { idiom: "妙不可言", meaning: "形容美妙到了极点，无法用言语表达。强调美好得难以言说，多用于形容感受、意境、体验等极其美妙。褒义。", context: "清晨的黄山云海妙不可言，仿佛置身于仙境之中，令人流连忘返。" },
  { idiom: "独树一帜", meaning: "指单独树立起一面旗帜，比喻独创新路、自成一家。强调风格独特、与众不同，多用于形容艺术、学术、方法等方面的独特性。褒义。", context: "这位导演的作品风格独树一帜，在叙事手法和视觉语言上都有大胆创新。" },
  { idiom: "无与伦比", meaning: "指事物非常完美，没有能跟它相比的。强调独一无二、同类中最好，程度极重，多用于赞美事物达到了极高的境界。褒义。", context: "北京冬奥会呈现出中国文化和冰雪文化、奥运文化的完美融合，给世界人民留下无与伦比的印象。" },
  { idiom: "叹为观止", meaning: "指赞美所见到的事物好到了极点。强调观者的赞叹之情，多用于形容景物、表演、艺术作品等令人极度欣赏。褒义，主语通常为人。", context: "还创新出‘花车斗彩’虚拟场景，令人叹为观止。" },
  { idiom: "前功尽弃", meaning: "指以前的功劳或努力全部废弃。强调因最后的失误或中途放弃而导致之前的努力付之东流，多用于形容功败垂成、令人惋惜的情形。贬义。", context: "实验已进入最后阶段，此时若放松要求，很可能前功尽弃。" },
  { idiom: "枉费心机", meaning: "指白费心思，形容费尽心机却毫无结果。强调用心计或谋划却未能达到目的，多用于形容算计落空、白费力气。贬义。", context: "他企图通过投机取巧蒙混过关，最终枉费心机，还是被识破了。" },
  { idiom: "殚精竭虑", meaning: "指用尽精力、费尽心思。强调为某件事付出全部精力和智慧，多用于形容为重大事业或难题而深思熟虑、倾尽心血。褒义。", context: "为了攻克这一世界级难题，科研团队殚精竭虑，历时十年终于取得突破。" },
  { idiom: "一掷千金", meaning: "指扔出千金，形容挥霍无度、花钱如流水，也形容为某件事不惜重金投入。强调花费巨大、毫不吝惜，多用于形容奢侈消费或豪爽投入（视语境可褒可贬）。中性或贬义。", context: "他在慈善拍卖会上一掷千金，拍下多件藏品用于支持乡村教育。" },
  { idiom: "竭尽全力", meaning: "指用尽全部的力量。强调不遗余力、倾尽所有去完成某事，多用于形容面对重要任务时的投入程度。褒义。", context: "面对突如其来的洪灾，救援人员竭尽全力抢救被困群众，争分夺秒转移受灾百姓。" },
  { idiom: "发扬光大", meaning: "指使美好的事物在原有基础上得到发展和提高。强调在继承的基础上进一步弘扬壮大，多用于形容优良传统、优秀文化、精神品质等的传承与发展。褒义。", context: "我们要把中华优秀传统文化发扬光大，让其在新时代焕发出更加璀璨的光芒。" },
  { idiom: "画龙点睛", meaning: "指画龙之后再点上眼睛，比喻在关键处加上一笔，使整体更加生动传神。强调在要害处用精炼之笔点明要旨，多用于形容写作、讲话、艺术创作中的关键之笔。褒义。", context: "文章结尾的这句话画龙点睛，将全文的主题升华到了一个新的高度。" },
  { idiom: "锦上添花", meaning: "指在锦缎上再绣上花，比喻在美好的基础上再增添美好。强调好上加好、美上加美，多用于形容在已有成绩上再增添新的光彩。褒义。", context: "这次获奖对他来说无疑是锦上添花，进一步坚定了他在艺术道路上继续前行的信心。" },
  { idiom: "拾遗补缺", meaning: "指捡取遗漏、弥补缺失，比喻补充别人或前人的不足。强调查漏补缺、补充完善，多用于形容对工作、制度、资料等的补充完善。褒义或中性。", context: "在整理史料时，他做了大量拾遗补缺的工作，为后人研究提供了宝贵的补充材料。" },
  { idiom: "无独有偶", meaning: "指虽然少见，但不只一个，竟然还有配对的。强调某种事物或现象不止一例、成对出现，多用于形容两件类似的事（多含贬义）接连出现。中性或贬义。", context: "就在同一天，另一座城市也发生了类似事故，无独有偶，暴露出的都是监管缺位的问题。" },
  { idiom: "不可否认", meaning: "指不能否认，表示承认某事确实存在或成立。强调事实确凿、无可辩驳，多用于承认某个客观事实（常与“但”搭配，引出转折）。中性。", context: "不可否认，我们在一些核心技术上仍存在短板，但这恰恰是努力的方向。" },
  { idiom: "不言自明", meaning: "指不用说明就能明白。强调道理或事实本身极为明显，无需多言。中性或褒义。", context: "绿水青山就是金山银山，这个道理不言自明，关键在于落到实处。" },
  { idiom: "求之不得", meaning: "指想找都找不到，形容迫切希望得到。强调渴望已久、正合心意，多用于形容对某人或某事物的急切期盼，得到后感到非常欣喜。中性或褒义。", context: "对于这个宝贵的学习机会，他求之不得，当即答应了下来。" },
  { idiom: "至关重要", meaning: "指非常重要，在事物发展中起关键作用。强调地位或作用极其重要，多用于形容因素、环节、决策等对全局的影响。褒义。", context: "粮食安全至关重要，必须牢牢把饭碗端在自己手中。" },
  { idiom: "沽名钓誉", meaning: "指用不正当的手段谋取名誉。强调刻意追求虚名、以手段骗取声誉，多用于批评追名逐利、名不副实的行为。贬义。", context: "真正的学者潜心钻研，不为沽名钓誉，而是追求真理与学问本身。" },
  { idiom: "不期而至", meaning: "指没有约定而突然到来。强调未经计划、意外出现，多用于形容事物（如困难、机会、客人等）的到来超出预期。中性。", context: "困难总是不期而至，但只要我们团结一致，就能克服一切。" },
  { idiom: "实至名归", meaning: "指有了真正的学识、本领或功业，自然就有声誉。强调名望和荣誉是凭实力和贡献赢得的，名副其实、当之无愧。褒义。", context: "这位科学家为航天事业奉献了毕生精力，荣获终身成就奖可谓实至名归。" },
  { idiom: "名副其实", meaning: "指名称或名声与实际相符合。强调名声与实质一致、不虚假，多用于形容人或事物确实配得上其称号或评价。褒义。", context: "这家老字号餐馆名副其实，菜品地道、服务周到，深受食客喜爱。" },
  { idiom: "急功近利", meaning: "指急于追求眼前的成效和利益。强调目光短浅、不顾长远。贬义。", context: "人才培养不能急功近利，需要遵循成长规律，久久为功。" },
  { idiom: "偷工减料", meaning: "指不按照产品或工程所规定的质量要求而暗中掺假或削减工序和用料。强调为降低成本而暗中削减必要的工序或材料，多用于批评施工、生产中的弄虚作假行为。贬义。", context: "这座桥梁被查出偷工减料，施工单位为了节省成本擅自减少了钢筋用量，存在严重安全隐患。" },
  { idiom: "花里胡哨", meaning: "形容颜色过分鲜艳繁杂，也比喻浮华而不实在。强调外表花哨、缺乏实质内容，多用于批评形式浮夸、华而不实的事物或做法。贬义。", context: "这款产品包装花里胡哨，但实际功能却很一般，消费者并不买账。" }
];


// 把数据挂到 window 上，方便 index.html 读取
window.NORM_DATA = NORM_DATA;
